const BASELINE={schema:3,profile:{name:'Joris',weight:70,week:0},tests:[{id:'initial-1',ex:'Développé couché',load:75,reps:3,rir:0,bw:null,date:null},{id:'initial-2',ex:'Développé militaire',load:45,reps:4,rir:0,bw:null,date:null},{id:'initial-3',ex:'Tractions lestées',load:15,reps:4,rir:0,bw:70,date:null}],workLoads:{'Développé incliné haltères':22,'Chest press':40},history:[],exerciseNotes:{},draft:null,dayOverrides:{},planOverrides:{},preferences:{sound:false,motion:true,autoRest:true},savedAt:null};
