function normalise(raw){if(!raw||typeof raw!=='object'||!Array.isArray(raw.tests))throw Error('Format invalide');let s;if(raw.schema===3){s={...clone(BASELINE),...raw,profile:{...BASELINE.profile,...raw.profile},preferences:{...BASELINE.preferences,...raw.preferences}}}else if('bodyWeight'in raw&&Array.isArray(raw.history)){s={...clone(BASELINE),profile:{name:'Joris',weight:raw.bodyWeight,week:raw.week},tests:raw.tests.map(t=>({...t,id:String(t.id),date:t.date||null})),workLoads:raw.workLoads||{},history:raw.history.map((h,i)=>({id:h.id||'import-'+i,date:h.date,name:h.name,day:program.findIndex(p=>p.day===h.day),week:h.week??null,duration:h.duration||0,sets:h.sets.map(x=>({...x,n:x.set||1})),imported:true})),draft:null};}else throw Error('Sauvegarde non reconnue');
const num=(n,a,b)=>typeof n==='number'&&Number.isFinite(n)&&n>=a&&n<=b;const validName=n=>typeof n==='string'&&n.length>0&&n.length<150;
if(!num(s.profile.weight,1,500)||!Number.isInteger(s.profile.week)||!num(s.profile.week,0,20)||!validName(s.profile.name))throw Error('Profil invalide');
if(!s.tests.every(t=>validName(t.ex)&&num(t.load,0,2000)&&Number.isInteger(t.reps)&&num(t.reps,1,100)&&num(t.rir??0,0,5)&&(t.bw==null||num(t.bw,1,500))&&(t.date==null||Number.isFinite(Date.parse(t.date)))))throw Error('Tests invalides');
if(!s.workLoads||typeof s.workLoads!=='object'||!Object.entries(s.workLoads).every(([k,v])=>validName(k)&&num(v,0,2000)))throw Error('Charges invalides');
if(!Array.isArray(s.history)||!s.history.every(h=>validName(h.name)&&Number.isFinite(Date.parse(h.date))&&Array.isArray(h.sets)&&h.sets.every(x=>validName(x.name)&&num(x.load,0,2000)&&num(x.reps,1,100)&&num(x.rir??0,0,5))))throw Error('Historique invalide');
s.tests=s.tests.map(t=>({...t,id:String(t.id||uid())}));s.history=s.history.map(h=>({...h,id:String(h.id||uid()),duration:num(h.duration,0,864000)?h.duration:0}));
if(s.draft){const d=s.draft;if(!Number.isInteger(d.day)||d.day<0||d.day>6||!Number.isFinite(d.started)||!Array.isArray(d.exercises)||!d.exercises.length||!d.exercises.every(e=>validName(e.name)&&Array.isArray(e.sets)&&e.sets.every(x=>num(x.load,0,2000)&&num(x.reps,0,100)&&num(x.rir,0,5))))throw Error('Séance en cours invalide');d.index=clamp(d.index||0,0,d.exercises.length-1);d.templateDay=Number.isInteger(d.templateDay)&&d.templateDay>=0&&d.templateDay<=5?d.templateDay:(d.day<6?d.day:0)}s.exerciseNotes=s.exerciseNotes||{};if(typeof s.exerciseNotes!=='object'||Array.isArray(s.exerciseNotes)||!Object.entries(s.exerciseNotes).every(([n,v])=>validName(n)&&typeof v==='string'&&v.length<=1000))throw Error('Notes invalides');s.dayOverrides=s.dayOverrides&&typeof s.dayOverrides==='object'&&!Array.isArray(s.dayOverrides)?s.dayOverrides:{};for(const wk of Object.keys(s.dayOverrides)){const map=s.dayOverrides[wk];if(!map||typeof map!=='object'||Array.isArray(map)||!num(Number(wk),0,20)||!Object.entries(map).every(([d,t])=>num(Number(d),0,6)&&(t==='rest'||num(t,0,5)))){delete s.dayOverrides[wk];continue}}
s.planOverrides=s.planOverrides&&typeof s.planOverrides==='object'&&!Array.isArray(s.planOverrides)?s.planOverrides:{};const validPlanExercise=e=>e&&typeof e==='object'&&validName(e.name)&&Array.isArray(e.sets)&&e.sets.length>=1&&e.sets.length<=12&&typeof e.reps==='string'&&e.reps.length>0&&e.reps.length<40&&num(e.rir,0,5)&&num(e.rest,15,900)&&e.sets.every(x=>x&&typeof x==='object'&&(x.load==null||num(x.load,0,2000))&&num(x.reps,0,100)&&num(x.rir,0,5)&&num(x.min??x.reps,0,100)&&num(x.max??x.reps,0,100));for(const wk of Object.keys(s.planOverrides)){const map=s.planOverrides[wk];if(!map||typeof map!=='object'||Array.isArray(map)||!num(Number(wk),0,20)){delete s.planOverrides[wk];continue}for(const day of Object.keys(map)){const list=map[day];if(!num(Number(day),0,6)||!Array.isArray(list)||!list.length||list.length>30||!list.every(validPlanExercise)){delete map[day];continue}map[day]=list.map(e=>({...e,sets:e.sets.map(x=>{const y={...x};delete y.done;return y})}))}if(!Object.keys(map).length)delete s.planOverrides[wk]}s.schema=3;return s;}
function loadState(){try{let x=localStorage.getItem(KEY)||localStorage.getItem('muscu-coach-v2');return x?normalise(JSON.parse(x)):clone(BASELINE)}catch{return clone(BASELINE)}}
let state=loadState(),tab='home',selectedDay=todayPlanDay(),selectionMode='auto',calendarKey=localDate(),previewWeek=state.profile.week||1,programMode='sessions',progressMode='overview',chartExercise='Développé couché',lastFocus=null,toastTimeout=null,audioCtx=null,wakeLock=null,planEditContext=null;
function save(){state.savedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));storageError=false;return true}catch{storageError=true;toast('Sauvegarde indisponible. Exporte tes données pour les conserver.');return false}}
const phase=(w=state.profile.week)=>PHASES.find(p=>w>=p.from&&w<=p.to)||PHASES[0];
const repRange=s=>{const a=String(s).match(/\d+/g)||[8];return {min:+a[0],max:+(a[1]||a[0])}};
const round=(n,inc)=>Math.round(n/inc)*inc;
function increment(name){if(/haltère|bulgare|marteau|incliné$|Rowing unilatéral$/.test(name))return /Élévation/.test(name)?1:2;if(/presse|Chest press|Hack|Leg |Mollet|Rowing machine|pec-deck/i.test(name))return 5;if(/poulie|corde/.test(name))return 1.25;return 2.5}
function refName(name){if(name==='Squat / Hack squat')return latestTest('Squat')?'Squat':'Hack squat';return name}
function latestTest(name){return [...state.tests].reverse().filter(t=>t.ex===name).sort((a,b)=>(b.date?Date.parse(b.date):0)-(a.date?Date.parse(a.date):0))[0]}
function e1rm(t){if(!t)return 0;const total=t.load+(t.ex==='Tractions lestées'?(t.bw||state.profile.weight):0);return total*(1+t.reps/30)}
function lastSets(name){for(const h of [...state.history].reverse()){const s=h.sets.filter(x=>x.name===name);if(s.length)return s}return []}
function suggestedLoad(ex,reps=ex.reps){if(Object.hasOwn(state.workLoads,ex.name))return state.workLoads[ex.name];const t=latestTest(refName(ex.name));if(!t)return null;const r=repRange(reps),mid=(r.min+r.max)/2,pct=mid<=5?.82:mid<=8?.76:mid<=10?.71:mid<=12?.67:mid<=15?.62:.57;let total=e1rm(t)*pct;if(ex.name==='Tractions lestées')total-=state.profile.weight;return Math.max(0,round(total,increment(ex.name)))}
function prescription(ex,w=state.profile.week){const p=phase(w);let n=ex.sets,reps=ex.reps,rir=ex.rir,method=ex.tag.startsWith('superset')?ex.tag.replace('superset','Superset'):'Séries classiques',load=suggestedLoad(ex),rest=ex.tag==='principal'?180:ex.tag.startsWith('superset')?90:n>=4?90:120,tempo=ex.tag==='principal'?'2–0–X–0':'2–0–1–0';
if(p.kind==='hypertrophy')rir=[3,2,1.5,1][w-1];
if(p.kind==='deload'){n=Math.max(1,Math.ceil(n*.55));rir=4;method='Volume allégé';}
let sets=[];if(p.kind==='strength'&&ex.tag==='principal'){const configs=[[4,5,.79,2],[5,4,.82,2],[5,3,.855,1.5],[1,3,.885,1]];const cfg=configs[w-6],t=latestTest(refName(ex.name)),external=pct=>t?Math.max(0,round(e1rm(t)*pct-(ex.name==='Tractions lestées'?state.profile.weight:0),increment(ex.name))):load;n=cfg[0];reps=String(cfg[1]);rir=cfg[3];load=external(cfg[2]);method=w===9?'Top set + back-off':'Force';for(let i=0;i<n;i++)sets.push({load,reps:cfg[1],rir,min:cfg[1],max:cfg[1],label:w===9?'Top':'Travail'});if(w===9)for(let i=0;i<3;i++)sets.push({load:external(cfg[2]-.1),reps:5,rir:2,min:5,max:5,label:'Back-off'});
}else if(p.kind==='heavy'&&ex.tag==='principal'){method='Top set + back-off';reps='6–10';rir=1;sets.push({load,reps:6,rir:1,min:6,max:8,label:'Top'});for(let i=1;i<n;i++)sets.push({load:load==null?null:Math.max(0,round(load*.9,increment(ex.name))),reps:10,rir:2,min:8,max:10,label:'Back-off'});
}else{const r=repRange(reps);for(let i=0;i<n;i++)sets.push({load,reps:r.max,rir,min:r.min,max:r.max,label:'Travail'});}return {...ex,sets,reps,rir,load,rest,tempo,method,calibrated:load!==null};}
function templateForDay(day,w=state.profile.week){const o=state.dayOverrides?.[w]?.[day];if(o==='rest')return null;if(Number.isInteger(o))return o;return day<6?day:null}
function defaultPlanFor(day,w=state.profile.week){const t=templateForDay(day,w);return t===null?[]:program[t].ex.map(e=>prescription(e,w))}
function hasPlanOverride(w,day){return Array.isArray(state.planOverrides?.[w]?.[day])}
function planFor(day,w=state.profile.week){const custom=state.planOverrides?.[w]?.[day];return custom?clone(custom):defaultPlanFor(day,w)}
function ensurePlanOverride(w,day){state.planOverrides||={};state.planOverrides[w]||={};if(!Array.isArray(state.planOverrides[w][day]))state.planOverrides[w][day]=defaultPlanFor(day,w).map(e=>clone(e));return state.planOverrides[w][day]}
function resetPlanOverride(w,day){if(!state.planOverrides?.[w]?.[day])return;delete state.planOverrides[w][day];if(!Object.keys(state.planOverrides[w]).length)delete state.planOverrides[w];save();render();toast('Séance remise au programme prévu.')}
function setDayAssignment(w,day,value){state.dayOverrides||={};const week=state.dayOverrides[w]||={};const def=day<6?day:'rest';if(value===def)delete week[day];else week[day]=value;if(!Object.keys(week).length)delete state.dayOverrides[w];if(state.planOverrides?.[w]?.[day]){delete state.planOverrides[w][day];if(!Object.keys(state.planOverrides[w]).length)delete state.planOverrides[w]}save();render();toast('Semaine '+w+' mise à jour · la séance de ce jour repart du programme prévu.');}
function resetWeekDays(w){if(state.dayOverrides?.[w]){delete state.dayOverrides[w];save();render();toast('Semaine '+w+' remise à l’organisation normale.')}}
function organizeWeekModal(w){showModal('Organiser la semaine '+w+'.',`<p class="small muted" style="margin-bottom:18px">Choisis quelle séance — ou repos — pour chaque jour. Ça ne change que la semaine ${w} : les autres semaines gardent leur organisation normale.</p><div class="stack">${WEEKDAYS.map((name,day)=>{const t=templateForDay(day,w);return `<div class="field"><label for="assign${day}">${name}</label><select id="assign${day}" data-input="assignDay" data-day="${day}">${program.map((p,i)=>`<option value="${i}" ${t===i?'selected':''}>${esc(p.name)}</option>`).join('')}<option value="rest" ${t===null?'selected':''}>Repos</option></select></div>`}).join('')}</div>${state.dayOverrides?.[w]?`<button class="link-btn" style="margin-top:16px" data-action="resetWeek:${w}">${icon('history')}Réinitialiser l’organisation de la semaine ${w}</button>`:''}`,[{label:'Fermer',fn:closeModal}],true)}
function workload(sets){return sets.reduce((sum,s)=>sum+s.load*s.reps,0)}
function draftStats(){const list=state.draft?.exercises||[];return{done:list.reduce((n,e)=>n+e.sets.filter(s=>s.done).length,0),total:list.reduce((n,e)=>n+e.sets.length,0)}}
function weeklyHistory(){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));const end=new Date(d);end.setDate(end.getDate()+7);return state.history.filter(h=>new Date(h.date)>=d&&new Date(h.date)<end)}
function toast(msg){clearTimeout(toastTimeout);$('#toast').textContent=msg;$('#toast').classList.remove('hidden');toastTimeout=setTimeout(()=>$('#toast').classList.add('hidden'),3600)}
function btn(label,action,kind='primary',ic=''){return `<button class="btn btn-${kind}" data-action="${action}">${label}${ic?icon(ic):''}</button>`}
function intro(title,subtitle,right=''){return `<div class="page-intro"><div><h1>${title}</h1><p>${subtitle}</p></div>${right}</div>`}
function empty(ic,title,text){return `<div class="empty">${icon(ic)}<h3>${title}</h3><p>${text}</p></div>`}
const TABINFO=[['home','grid','Tableau de bord','Accueil'],['program','calendar','Programme','Programme'],['workout','dumbbell','Ma séance','Séance'],['progress','chart','Progression','Progrès'],['settings','settings','Réglages','Réglages']];
function shell(){const brand=`<span class="brand-symbol">${icon('dumbbell')}</span><span class="brand-name">MUSCU<span class="orange">.</span><small>COACH PRO</small></span>`;$('.sidebar').innerHTML=`<a class="brand" href="#home" aria-label="Accueil Muscu Coach Pro">${brand}</a><div class="nav-label">TON ESPACE ATHLÈTE</div><nav class="nav-list" aria-label="Navigation principale">${TABINFO.map(([id,i,name])=>`<button class="nav-btn" data-tab="${id}">${icon(i)}<span>${name}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-cycle"><div class="row between"><span class="eyebrow muted">CYCLE ACTUEL</span>${icon('bolt')}</div><p id="sidePhase"></p><div class="mini-progress"><i id="sideProgress"></i></div></div><button class="profile-btn" data-tab="settings"><span class="avatar" id="avatar"></span><span><b id="profileName"></b><small>Prise de masse & force</small></span></button></div>`;$('.topbar').innerHTML=`<a class="brand" href="#home">${brand}</a><div class="breadcrumb">Mon espace <span style="padding-left:10px">/</span><b id="crumb"></b></div><div class="top-actions"><span class="top-date">${new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})}</span><span class="pill orange">${icon('bolt')}<span id="weekBadge"></span></span><button class="icon-btn" data-action="help" aria-label="Comprendre les repères">${icon('info')}</button></div>`;$('.mobile-nav').innerHTML=TABINFO.map(([id,i,,name])=>`<button class="nav-btn" data-tab="${id}">${icon(i)}<span>${name}</span></button>`).join('');}
function updateShell(){if($('.top-date'))$('.top-date').textContent=fullDateLabel();document.body.classList.toggle('reduced',!state.preferences.motion);$('#weekBadge').textContent=`Semaine ${state.profile.week}`;$('#sidePhase').textContent=phase().short+' · S'+state.profile.week;$('#sideProgress').style.width=state.profile.week/20*100+'%';$('#avatar').textContent=state.profile.name.slice(0,1).toUpperCase();$('#profileName').textContent=state.profile.name;$('#crumb').textContent=TABINFO.find(t=>t[0]===tab)[2];$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);if(b.classList.contains('nav-btn')){if(b.dataset.tab===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}})}
function navigate(next,{scroll=true}={}){if(!TABINFO.some(t=>t[0]===next))return;if(next==='home'){selectionMode='auto';selectedDay=todayPlanDay()}tab=next;render();if(scroll)window.scrollTo({top:0,behavior:'instant'});try{history.replaceState(null,'','#'+tab)}catch{} }
function render(){syncCalendar(false);updateShell();const main=$('#view');main.innerHTML=({home:homeView,program:programView,workout:workoutView,progress:progressView,settings:settingsView,nutrition:()=>nutritionView()})[tab]();main.classList.remove('page-enter');void main.offsetWidth;main.classList.add('page-enter');renderTimer();if(tab==='workout')$('#exerciseTabs .active')?.scrollIntoView({block:'nearest',inline:'center'});if(tab==='program')$('#weekSelector .active')?.scrollIntoView({block:'nearest',inline:'center'});}
function homeView(){const ph=phase(),wk=weeklyHistory(),totalVolume=state.history.reduce((n,h)=>n+workload(h.sets),0),cal=ph.kind==='test';return intro(`Prêt, ${esc(state.profile.name)} <span class="orange">?</span>`,`${fullDateLabel()} · Un objectif, une séance à la fois.`,`<span class="pill">${icon('target')} Prise de masse</span>`)+homeHeroHTML()+weekSummaryExtras()+`
${cal?`<div class="calibration-banner"><div class="row">${icon('target')}<div><b>${state.profile.week===0?'Tes fondations sont déjà là.':'Fais le point sur tes repères.'}</b><p>${state.tests.length} tests enregistrés · ${ph.desc}</p></div></div>${btn('Voir mes références','showRefs','outline')}</div>`:''}
<div class="metrics stagger"><div class="metric"><span class="metric-icon">${icon('dumbbell')}</span><div><strong>${state.history.length}</strong><p>Séances enregistrées</p></div></div><div class="metric"><span class="metric-icon">${icon('weight')}</span><div><strong>${totalVolume>=1000?fmt(totalVolume/1000):fmt(totalVolume)} <small>${totalVolume>=1000?'t':'kg'}</small></strong><p>Volume renseigné cumulé</p></div></div><div class="metric"><span class="metric-icon">${icon('target')}</span><div><strong>${fmt(state.profile.weight)} <small>kg</small></strong><p>Poids du corps</p></div></div></div>
<div class="home-lower"><section class="card"><div class="row between card-head"><h2>Tes repères de force</h2><button class="link-btn" data-action="showRefs">Voir tout ${icon('up')}</button></div>${['Développé couché','Développé militaire','Tractions lestées'].map((name,i)=>{const t=latestTest(name);return `<div class="strength-row"><span class="ex-index">0${i+1}</span><div class="strength-info"><b>${name}</b><p>${t?`${fmt(t.load)} kg${name==='Tractions lestées'?' de lest':''} × ${t.reps} reps`:'À renseigner'} · e1RM${name==='Tractions lestées'?' total':''}</p></div><strong>${t?fmt(e1rm(t)):'—'}<small> kg</small></strong></div>`}).join('')}</section><section class="card block-card"><div class="row between"><span class="eyebrow" style="color:var(--blue)">BLOC ${ph.code} / 08</span><span class="small muted">S${state.profile.week} / 20</span></div><h2 class="block-name">${ph.name}</h2><p class="block-weeks">${ph.desc}</p><div class="track" aria-hidden="true">${Array.from({length:20},(_,i)=>`<i class="${i<state.profile.week?'past':i===state.profile.week?'now':''}"></i>`).join('')}</div><button class="link-btn" data-action="showCycle">Explorer mon cycle ${icon('arrow')}</button></section></div>
<div class="section-heading"><h2>Le travail accompli</h2><button class="link-btn" data-action="showHistory">Historique ${icon('up')}</button></div><section class="card">${state.history.length?historyRows(state.history.slice(-2).reverse()):empty('history','La première séance donne le ton.','Valide tes séries pendant l’entraînement. Ton bilan et tes prochaines charges apparaîtront ici.')}</section>`;}
function programView(){return intro('Ton plan de jeu.','Organise tes 7 jours et personnalise chaque séance avant de la lancer.',`<button class="icon-btn" data-action="help" aria-label="Comprendre le cycle">${icon('info')}</button>`)+`<div class="row between wrap" style="margin-bottom:20px"><div class="segmented"><button class="seg-btn ${programMode==='sessions'?'active':''}" data-action="programMode:sessions">Les séances</button><button class="seg-btn ${programMode==='cycle'?'active':''}" data-action="programMode:cycle">Le cycle complet</button></div><span class="pill orange">Semaine actuelle : ${state.profile.week}</span></div>`+(programMode==='cycle'?`<div class="cycle-timeline">${PHASES.map(p=>`<article class="phase-row ${phase()===p?'current':''}"><div class="phase-range">${p.from===p.to?'S'+p.from:p.from+'–'+p.to}</div><div style="flex:1"><h3>${p.name}</h3><p>${p.desc}</p></div><button class="icon-btn" data-action="preview:${p.from}" aria-label="Voir ${p.name}">${icon('chevron')}</button></article>`).join('')}</div>`:`<div class="week-selector" id="weekSelector" aria-label="Semaine à consulter">${Array.from({length:21},(_,w)=>`<button class="week-tile ${w===previewWeek?'active':''} ${w===state.profile.week?'current':''}" data-action="preview:${w}" aria-pressed="${w===previewWeek}"><small>SEM.</small>${String(w).padStart(2,'0')}</button>`).join('')}</div><div class="plan-preview-label"><span>${phase(previewWeek).name}${previewWeek!==state.profile.week?' · Aperçu':''}</span><div class="row" style="gap:14px">${previewWeek!==state.profile.week?`<button class="link-btn orange" data-action="setWeek:${previewWeek}">Choisir cette semaine ${icon('arrow')}</button>`:''}<button class="link-btn" data-action="organizeWeek">${icon('edit')}Organiser ma semaine</button></div></div>${phase(previewWeek).kind==='test'?`<div class="note" style="margin-bottom:16px">${icon('info')}${phase(previewWeek).name} : tu peux enregistrer tes tests de force dans l’onglet Références, en plus de tes séances normales ci-dessous.</div>`:''}${`<div class="program-grid stagger">${WEEKDAYS.map((_,i)=>programDayHTML(i,previewWeek)).join('')}</div>`}`);}
function workoutView(){const d=state.draft;if(!d){const wk=state.profile.week||1,t=templateForDay(selectedDay,wk),tpl=t===null?null:program[t],exs=t===null?[]:planFor(selectedDay,wk);return intro('Entre dans ta séance.','Tes séries, tes charges, ton rythme.')+`<div class="session-overview"><section class="card big-start"><div class="row between"><span class="pill orange">${WEEKDAYS[selectedDay]}</span><span class="eyebrow muted">${tpl?tpl.focus:'Repos programmé'}</span></div><h2>${tpl?tpl.name.replace(' + ','<br><span class="orange">+ '):'JOUR DE<br><span class="orange">REPOS</span>'}</span></h2><p class="muted small">${tpl?exs.length+' exercices · '+exs.reduce((n,e)=>n+e.sets.length,0)+' séries':'Aucune séance programmée ce jour. Choisis-en une ci-dessous si tu veux t’entraîner quand même.'}</p><div class="spacer"></div>${tpl?`<div class="stack">${btn('Modifier / réorganiser','editCurrentPlan:'+selectedDay,'outline','edit')}${btn('Lancer ma séance','start:'+selectedDay,'primary','play')}</div>`:''}<div class="divider"></div><label for="chooseDay">Choisir un autre jour</label><select id="chooseDay" data-input="chooseDay">${WEEKDAYS.map((name,i)=>{const ti=templateForDay(i,wk);return `<option value="${i}" ${i===selectedDay?'selected':''}>${name} · ${ti===null?'Repos':program[ti].name}</option>`}).join('')}</select></section><section class="card"><div class="card-head"><h2>Tout est prêt.</h2></div><div class="divider"></div><div class="stack"><div class="row">${icon('save','orange')}<div><b class="small">Reprise automatique</b><p class="small muted">Tes saisies restent en mémoire.</p></div></div><div class="row">${icon('timer','orange')}<div><b class="small">Repos synchronisé</b><p class="small muted">Il démarre après une série validée.</p></div></div><div class="row">${icon('chart','orange')}<div><b class="small">La suite se prépare</b><p class="small muted">Un bilan et tes prochaines charges.</p></div></div></div><div class="note" style="margin-top:27px">${icon('info')}Renseigne uniquement ce que tu réalises. Une série n’est enregistrée qu’après validation.</div></section></div>`}
const e=d.exercises[d.index],stats=draftStats(),last=lastSets(e.name),complete=e.sets.every(s=>s.done);return `<div class="workout-topline"><div><div class="eyebrow muted">${WEEKDAYS[d.day]} · SEMAINE ${d.week}</div><div class="row" style="margin-top:6px">${icon('clock','orange')}<span class="elapsed" id="elapsed">${timeStr((Date.now()-d.started)/1000)}</span><span class="micro muted">en cours</span></div></div><div class="row workout-actions">${btn('Adapter','adapt','outline','edit')}${btn('Terminer','finish','primary','check')}${btn('Annuler la séance','discard','outline','close')}</div></div><div class="workout-layout"><div><div class="exercise-tabs" id="exerciseTabs" aria-label="Exercices de la séance">${d.exercises.map((ex,i)=>`<button class="ex-tab ${i===d.index?'active':''} ${ex.sets.every(s=>s.done)?'complete':''}" data-action="exercise:${i}" aria-label="${i+1}. ${esc(ex.name)}" aria-pressed="${i===d.index}">${ex.sets.every(s=>s.done)?'✓':String(i+1).padStart(2,'0')}</button>`).join('')}</div><article class="card active-exercise"><div class="row between"><span class="eyebrow orange">EXERCICE ${String(d.index+1).padStart(2,'0')} / ${String(d.exercises.length).padStart(2,'0')}</span><button class="icon-btn" data-action="exerciseInfo" aria-label="Voir les consignes et les repères">${icon('info')}</button></div><h2>${esc(e.name)}</h2><div class="target-chips"><span class="pill">${e.sets.length} séries</span><span class="pill">${esc(e.reps)} reps</span><button class="pill" data-action="help" style="min-height:0">RIR ${e.rir}</button><button class="pill orange" data-action="restSettings" style="min-height:0">${icon('timer')}Séries : ${timeStr(e.rest)}</button><button class="pill orange" data-action="restSettings" style="min-height:0">Entre exos : ${timeStr(exerciseRestDuration(e))}</button>${e.tag.startsWith('superset')?`<span class="pill blue">${esc(e.method)}</span>`:''}</div><div class="set-grid header" aria-hidden="true"><span>#</span><span style="text-align:center">${e.name==='Tractions lestées'?'Lest · kg':'Charge · kg'}</span><span style="text-align:center">Reps</span><span style="text-align:center">RIR</span><span style="text-align:center">Fait</span></div>${e.sets.map((s,i)=>`<div class="set-grid set-item ${s.done?'done':''} ${i===e.sets.findIndex(x=>!x.done)?'current':''}" data-setrow="${i}"><div class="set-no" title="${esc(s.label)}">${i+1}</div>${['load','reps','rir'].map(k=>`<input aria-label="Série ${i+1}, ${k==='load'?'charge en kilogrammes':k==='reps'?'répétitions':'RIR'}" type="number" inputmode="decimal" min="0" ${k==='rir'?'max="5"':k==='reps'?'max="100"':'max="2000"'} step="${k==='reps'?'1':k==='rir'?'.5':'.25'}" value="${s[k]}" data-set="${i}" data-field="${k}" ${s.done?'disabled':''}>`).join('')}<button class="set-check" data-action="check:${i}" aria-label="${s.done?'Annuler la validation':'Valider'} de la série ${i+1}" aria-pressed="${!!s.done}">${icon('check')}</button></div>`).join('')}<div class="set-management"><button class="link-btn" data-action="addSet">${icon('plus')}Ajouter ${e.tag.startsWith('superset')?'une paire':'une série'}</button><button class="link-btn" data-action="removeSet" ${e.sets.length<=1?'disabled':''}>Retirer ${e.tag.startsWith('superset')?'une paire':'une série'}</button></div><div class="exercise-tools"><button class="link-btn" data-action="copyLoad">${icon('edit')} Copier la 1re charge</button><button class="link-btn" data-action="restStart">${icon('timer')} Lancer le repos</button></div>${exerciseMemoryHTML(e)}<div class="training-notes">${last.length?`<b>La dernière fois</b> · ${last.map(s=>fmt(s.load)+' kg × '+s.reps).join(' / ')}`:e.calibrated?'<b>Point de départ</b> · Une proposition à ajuster selon ton ressenti.':'<b>Charge à régler</b> · Aucune référence pour cet exercice. Renseigne ta charge avant de valider.'}${e.name==='Tractions lestées'?'<br>Saisis uniquement le lest ajouté. Ton poids de corps est pris en compte pour l’estimation.':''}${e.method.includes('back-off')?'<br>'+e.sets.map(s=>s.label+' : '+s.min+'–'+s.max+' reps').join(' · '):''}</div></article><div class="exercise-navigate"><button class="btn btn-outline" data-action="exercise:${d.index-1}" ${d.index===0?'disabled':''}>${icon('back')}Précédent</button><button class="btn ${complete?'btn-primary':'btn-outline'}" data-action="${d.index===d.exercises.length-1?'finish':'exercise:'+(d.index+1)}">${d.index===d.exercises.length-1?'Bilan de séance':'Exercice suivant'}${icon('arrow')}</button></div><div class="live-progress"><div class="row between"><span>${stats.done} / ${stats.total} séries validées</span><span>${Math.round(stats.done/stats.total*100)} %</span></div><div class="mini-progress"><i style="width:${stats.done/stats.total*100}%"></i></div></div><button class="link-btn" data-action="discard" style="margin-top:25px">Abandonner cette séance</button></div><aside class="card queue-card"><span class="eyebrow muted">DANS TA SÉANCE</span>${d.exercises.map((ex,i)=>`<button class="queue-item ${i===d.index?'current':''}" data-action="exercise:${i}">${icon(ex.sets.every(s=>s.done)?'check':'dumbbell')}<span>${esc(ex.name)}</span><small>${ex.sets.filter(s=>s.done).length}/${ex.sets.length}</small></button>`).join('')}<div class="note" style="margin-top:20px">Tes séries sont conservées même si tu quittes cet écran.</div></aside></div>`;}
function historyRows(items){return items.map(h=>{const c=h.completion,ratio=c&&c.total?c.done/c.total:1,partial=ratio<1;return `<details class="history-row"><summary><div class="history-date">${new Date(h.date).getDate()}<small>${new Date(h.date).toLocaleDateString('fr-FR',{month:'short'})}</small></div><div class="history-info"><b>${esc(h.name)}</b>${partial?`<span class="pill ${ratio>=0.7?'orange':'red'}" style="margin-left:6px">${c.done}/${c.total}</span>`:''}${h.records?.length?'<span class="record-badge">'+icon('trophy')+h.records.length+' record'+(h.records.length>1?'s':'')+'</span>':''}<p>${h.sets.length} séries${h.duration?' · '+Math.max(1,Math.round(h.duration/60))+' min':''}${h.week!=null?' · S'+h.week:''}</p></div><span class="history-vol">${fmt(workload(h.sets)/1000)} t</span>${icon('chevron')}</summary><div class="history-detail">${compactResults(h)}<button class="btn btn-outline btn-wide" style="margin-bottom:14px" data-action="showRecap:${esc(h.id)}">Ouvrir le bilan complet ${icon('arrow')}</button><button class="link-btn" style="color:#f7a5a5" data-action="deleteHistory:${esc(h.id)}">Supprimer cette séance</button></div></details>`}).join('')}
function progressPoints(name){const points=state.tests.filter(t=>t.ex===name).map(t=>({date:t.date,value:e1rm(t),type:'Test'}));for(const h of state.history){const sets=h.sets.filter(s=>s.name===name);if(sets.length)points.push({date:h.date,value:Math.max(...sets.map(s=>e1rm({...s,ex:name,bw:h.bodyWeight||state.profile.weight}))),type:'Séance'})}return points.sort((a,b)=>(a.date?new Date(a.date).getTime():0)-(b.date?new Date(b.date).getTime():0)).slice(-12)}
function chartHTML(name){const data=progressPoints(name);if(!data.length)return empty('chart','Ta courbe commence avec un repère.','Ajoute un test ou termine une séance sur cet exercice pour suivre ton évolution.');const values=data.map(d=>d.value),min=Math.max(0,Math.floor(Math.min(...values)*.85/5)*5),max=Math.max(min+10,Math.ceil(Math.max(...values)*1.08/5)*5),width=620,height=240,left=45,right=595,top=20,bottom=198,point=(d,i)=>({x:data.length===1?320:left+(right-left)*i/(data.length-1),y:bottom-(d.value-min)/(max-min)*(bottom-top)}),pts=data.map(point),path=pts.map((p,i)=>(i?'L':'M')+p.x.toFixed(1)+','+p.y.toFixed(1)).join(' ');return `<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Évolution du maximum estimé pour ${esc(name)}"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#ff7947" stop-opacity=".18"/><stop offset="100%" stop-color="#ff7947" stop-opacity="0"/></linearGradient></defs>${Array.from({length:4},(_,i)=>{const y=top+(bottom-top)*i/3;return `<line class="chart-grid" x1="${left}" x2="${right}" y1="${y}" y2="${y}"/><text class="chart-axis" x="0" y="${y+4}">${fmt(max-(max-min)*i/3,0)}</text>`}).join('')}${pts.length>1?`<path d="${path}L${right},${bottom}L${left},${bottom}Z" fill="url(#chartFill)"/><path class="chart-line" d="${path}"/>`:''}${pts.map((p,i)=>`<circle class="chart-point" cx="${p.x}" cy="${p.y}" r="5" tabindex="0" role="button" aria-label="${data[i].type} ${esc(dateFr(data[i].date))}, ${fmt(data[i].value)} kilogrammes" data-action="chartPoint:${i}"><title>${fmt(data[i].value)} kg · ${dateFr(data[i].date)}</title></circle>`).join('')}<text class="chart-axis" x="${left}" y="226">${dateFr(data[0].date)}</text>${data.length>1?`<text class="chart-axis" x="${right}" y="226" text-anchor="end">${dateFr(data.at(-1).date)}</text>`:''}</svg><p class="chart-detail" id="chartDetail">${data.length===1?'Premier repère enregistré. La courbe se dessinera avec les prochaines séances.':'Sélectionne un point pour voir sa valeur.'}</p>`}
function progressView(){const tabs=`<div class="segmented" style="margin-bottom:24px">${[['overview','Vue d’ensemble'],['history','Historique'],['records','Records'],['tests','Références']].map(([k,label])=>`<button class="seg-btn ${progressMode===k?'active':''}" data-action="progressMode:${k}">${label}</button>`).join('')}</div>`;let content='';if(progressMode==='records'){content=recordsView()}else if(progressMode==='overview'){const names=[...new Set([...state.tests.map(t=>t.ex),...state.history.flatMap(h=>h.sets.map(s=>s.name))])];if(!names.includes(chartExercise)&&names.length)chartExercise=names[0];content=`<div class="grid3">${['Développé couché','Développé militaire','Tractions lestées'].map(n=>{const t=latestTest(n);return `<div class="ref-card"><h3>${n}</h3><div class="ref-value">${t?fmt(e1rm(t)):'—'} <small>kg</small></div><p class="ref-source">e1RM ${n==='Tractions lestées'?'corps + lest':'estimé'}</p></div>`}).join('')}</div><div class="spacer"></div><section class="card chart-card"><div class="row between card-head wrap"><div><h2>De plus en plus fort.</h2><p class="micro muted" style="margin-top:6px">Maximum estimé · Epley · kg</p></div><select aria-label="Exercice du graphique" data-input="chartExercise" style="max-width:235px">${names.map(n=>`<option ${n===chartExercise?'selected':''}>${esc(n)}</option>`).join('')}</select></div>${chartHTML(chartExercise)}</section><div class="section-heading"><h2>Tes dernières séances</h2><button class="link-btn" data-action="showHistory">Tout voir ${icon('up')}</button></div><section class="card">${state.history.length?historyRows(state.history.slice(-3).reverse()):empty('history','Du concret, bientôt ici.','Tes séances enregistrées alimenteront cet historique et tes courbes.')}</section>`}else if(progressMode==='history'){content=`<section class="card"><div class="row between card-head"><h2>${state.history.length} séance${state.history.length>1?'s':''} enregistrée${state.history.length>1?'s':''}</h2><span class="small muted">${fmt(state.history.reduce((n,h)=>n+workload(h.sets),0)/1000)} t</span></div>${state.history.length?historyRows([...state.history].reverse()):empty('calendar','Ton carnet est prêt.','Une fois ta séance terminée, tu retrouveras chaque charge, répétition et série ici.')}<div class="note" style="margin-top:20px">Volume renseigné = charge saisie × répétitions. Le poids du corps n’y est pas ajouté et les haltères ne sont pas doublés automatiquement.</div></section>`}else{content=`<section class="card"><div class="row between card-head"><h2>Références de force</h2>${btn('Ajouter','test:new','primary','plus')}</div>${state.tests.length?[...state.tests].reverse().map(t=>`<article class="test-row"><div class="row between wrap"><div><h3>${esc(t.ex)}</h3><p class="small muted">${fmt(t.load)} kg${t.ex==='Tractions lestées'?' de lest':''} × ${t.reps} · RIR ${t.rir}</p></div><span class="pill orange">e1RM ${fmt(e1rm(t))} kg</span></div><div class="row between" style="margin-top:12px"><span class="micro muted">${dateFr(t.date)}${t.ex==='Tractions lestées'?' · PDC '+fmt(t.bw||state.profile.weight)+' kg':''}</span><div class="actions"><button class="icon-btn" data-action="test:${esc(t.id)}" aria-label="Modifier le test ${esc(t.ex)}">${icon('edit')}</button><button class="icon-btn" data-action="deleteTest:${esc(t.id)}" aria-label="Supprimer le test ${esc(t.ex)}">${icon('trash')}</button></div></div></article>`).join(''):empty('target','Ajoute ton premier repère.','Une charge, un nombre de répétitions et une marge pour calibrer ton cycle.')}</section><div class="spacer"></div><section class="card"><div class="row between card-head"><h2>Charges de travail</h2><button class="link-btn" data-action="working:new">${icon('plus')}Ajouter</button></div><p class="small muted" style="margin-top:8px">Elles restent séparées de tes tests de force.</p>${Object.entries(state.workLoads).map(([name,value])=>`<div class="working-row row between"><b>${esc(name)}</b><div class="row"><strong>${fmt(value)} kg</strong><button class="icon-btn" data-action="working:${esc(name)}" aria-label="Modifier la charge ${esc(name)}">${icon('edit')}</button></div></div>`).join('')}</section>`}return intro('Le progrès se mesure.','Tes efforts deviennent des repères.')+tabs+content}
function settingsView(){return intro('Ta façon de t’entraîner.','Les bons réglages, au bon endroit.')+`<div class="settings-grid"><section class="card"><h2 class="settings-heading">Ton profil & ton cycle</h2><form id="profileForm"><div class="field-grid"><div class="field"><label for="profileNameInput">Prénom</label><input id="profileNameInput" name="name" value="${esc(state.profile.name)}" required maxlength="50"></div><div class="field"><label for="profileWeight">Poids du corps · kg</label><input id="profileWeight" name="weight" type="number" value="${state.profile.weight}" min="1" max="500" step=".1" required></div><div class="field" style="grid-column:1/-1"><label for="profileWeek">Semaine du cycle</label><select id="profileWeek" name="week">${Array.from({length:21},(_,w)=>`<option value="${w}" ${w===state.profile.week?'selected':''}>Semaine ${w} · ${phase(w).short}</option>`).join('')}</select></div></div><button class="btn btn-primary btn-wide" type="submit" style="margin-top:22px">${icon('check')}Enregistrer les réglages</button></form><div class="note" style="margin-top:20px">Le cycle avance quand tu le décides. Une nouvelle semaine ne s’active pas automatiquement.</div></section><section class="card"><h2 class="settings-heading">Pendant la séance</h2>${[['autoRest','Repos automatique','Après une série, ou après la paire en superset.'],['sound','Signal sonore','Un signal discret à la fin du repos, si l’app est ouverte.'],['motion','Animations','Transitions et retours visuels pendant tes actions.']].map(([key,title,desc])=>`<div class="toggle-row"><div><b>${title}</b><p>${desc}</p></div><button class="switch" role="switch" aria-checked="${state.preferences[key]}" aria-label="${title}" data-action="toggle:${key}"></button></div>`).join('')}<div class="note" style="margin-top:20px">Le chronomètre se recale au retour dans l’app. Le son dépend des autorisations du navigateur.</div></section><section class="card"><h2 class="settings-heading">Tes données, avec toi.</h2><p class="small muted">La sauvegarde reste dans ce navigateur. Pour changer d’appareil ou de fichier, exporte puis importe ton carnet.</p><div class="row wrap" style="margin-top:21px">${btn('Exporter','export','outline','download')}${btn('Importer','import','outline','upload')}</div><p class="micro muted" style="margin-top:17px">Muscu Coach Pro · 3.2 · Compatible avec les sauvegardes V2 et V3.</p>${state.savedAt?`<p class="micro muted" style="margin-top:6px">Dernière sauvegarde : ${new Date(state.savedAt).toLocaleString('fr-FR')}</p>`:''}</section><section class="card"><h2 class="settings-heading">Comprendre tes repères</h2><p class="small muted">RIR, e1RM, back-off et progression : les termes du programme, expliqués simplement.</p><div class="spacer"></div>${btn('Le guide rapide','help','outline','info')}<div class="divider"></div><button class="link-btn" style="color:#ed9999" data-action="reset">Réinitialiser toutes les données</button></section></div>`}
let modalActions={},modalReturnFocus=null;
function showModal(title,content,actions=[],wide=false){modalReturnFocus=document.activeElement;modalActions={};$('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialogTitle"><div class="modal-head"><h2 id="dialogTitle">${esc(title)}</h2><button class="icon-btn" data-action="closeModal" aria-label="Fermer">${icon('close')}</button></div>${content}${actions.length?`<div class="modal-actions">${actions.map((a,i)=>{modalActions['m'+i]=a.fn;return `<button class="btn btn-${a.kind||'primary'}" data-modal-action="m${i}">${a.label}</button>`}).join('')}</div>`:''}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.modal input,.modal select,.modal button')?.focus());}
function closeModal(){$('#modalRoot').innerHTML='';document.body.style.overflow='';modalActions={};if(modalReturnFocus?.isConnected)modalReturnFocus.focus();}
function confirmDialog(title,message,fn,label='Confirmer'){showModal(title,`<p class="small muted">${message}</p>`,[{label:'Annuler',kind:'outline',fn:closeModal},{label,fn:()=>{closeModal();fn()}}]);}
function startWorkout(day,w=state.profile.week){if(state.draft){showModal('Une séance est déjà en cours.',`<p class="muted small">${esc(program[state.draft.templateDay].name)} · ${draftStats().done} séries validées. Tu peux la reprendre ou l’abandonner pour en commencer une autre.</p>`,[{label:'Reprendre',fn:()=>{closeModal();navigate('workout')}},{label:'Abandonner & changer',kind:'danger',fn:()=>{state.draft=null;save();closeModal();startWorkout(day,w)}}]);return}
if(w!==state.profile.week){confirmDialog('Utiliser la semaine '+w+' ?',`Le cycle passera en ${esc(phase(w).name.toLowerCase())}. Tes séries seront calculées pour cette semaine.`,()=>beginWorkout(day,w),'Démarrer la séance');return}beginWorkout(day,w)}
function beginWorkout(day,w){const t=templateForDay(day,w);if(t===null){toast('Aucune séance programmée ce jour — choisis-en une, ou réorganise ta semaine.');return}state.profile.week=w;selectedDay=day;state.draft={id:uid(),day,templateDay:t,week:w,bodyWeight:state.profile.weight,started:Date.now(),index:0,rest:null,exercises:planFor(day,w).map(e=>({...e,sets:e.sets.map(s=>({...s,load:s.load??0,done:false}))}))};save();navigate('workout');requestWakeLock();}
async function requestWakeLock(){try{if(navigator.wakeLock&&document.visibilityState==='visible'&&state.draft&&!wakeLock)wakeLock=await navigator.wakeLock.request('screen');if(wakeLock)wakeLock.addEventListener('release',()=>wakeLock=null)}catch{}}
function releaseWake(){try{wakeLock?.release()}catch{}wakeLock=null}
function setExercise(index){if(!state.draft)return;state.draft.index=clamp(index,0,state.draft.exercises.length-1);save();render();}
function toggleSet(index){const d=state.draft,e=d?.exercises[d.index],s=e?.sets[index];if(!s)return;if(s.done){s.done=false;d.rest=null;save();render();return}const row=$(`[data-setrow="${index}"]`),inputs=[...row.querySelectorAll('input')];if(inputs.some(x=>x.value.trim()==='')){toast('Renseigne la charge, les répétitions et le RIR.');return}const vals=Object.fromEntries(inputs.map(i=>[i.dataset.field,Number(i.value)]));if(!Number.isFinite(vals.load)||vals.load<0||vals.load>2000||!Number.isInteger(vals.reps)||vals.reps<1||vals.reps>100||!Number.isFinite(vals.rir)||vals.rir<0||vals.rir>5){toast('Vérifie la charge, les reps et le RIR de 0 à 5.');return}if(vals.load===0&&!e.allowZero&&!/Tractions|dips/i.test(e.name)){toast('Règle ta charge avant de valider cette série.');return}Object.assign(s,vals,{done:true});let doRest=true;if(e.tag.startsWith('superset')){const peer=d.exercises.findIndex((x,i)=>i!==d.index&&x.tag===e.tag);if(peer>=0&&d.exercises[peer].sets[index]&&!d.exercises[peer].sets[index].done){d.index=peer;doRest=false;toast('Superset : enchaîne avec '+d.exercises[peer].name+'.')}else if(peer>=0&&d.exercises[peer].sets.some(x=>!x.done)){d.index=Math.min(d.index,peer)}}if(doRest&&state.preferences.autoRest)d.rest=nextRest(d,e);save();render();if(e.sets.every(x=>x.done)&&!e.tag.startsWith('superset'))toast('Exercice complété. Bien joué !');}
function exerciseRestDuration(e){const n=Number(state.preferences.exerciseRest);return Number.isFinite(n)&&n>=15&&n<=900?n:Math.min(900,e.rest+60)}
function nextRest(d,e){
 if(d.exercises.every(x=>x.sets.every(s=>s.done)))return null;
 const group=e.tag.startsWith('superset')?d.exercises.filter(x=>x.tag===e.tag):[e];
 const between=group.every(x=>x.sets.every(s=>s.done));
 const seconds=between?exerciseRestDuration(e):e.rest;
 return {end:Date.now()+seconds*1000,total:seconds,paused:null,kind:between?'exercise':'set'};
}
function startRest(seconds){if(!state.draft)return;const d=state.draft;if(seconds!=null)d.rest={end:Date.now()+seconds*1000,total:seconds,paused:null,kind:'set'};else d.rest=nextRest(d,d.exercises[d.index]);save();renderTimer();}

function restSeconds(){const r=state.draft?.rest;return r?Math.max(0,r.paused??Math.ceil((r.end-Date.now())/1000)):0}
function renderTimer(){const r=state.draft?.rest;document.body.classList.toggle('timer-running',!!r);if(!r){$('#timerDock').innerHTML='';return}const left=restSeconds();$('#timerDock').innerHTML=`<div class="timer-dock" role="region" aria-label="Chronomètre de repos"><div class="timer-circle"><svg viewBox="0 0 48 48" aria-hidden="true"><circle class="ring-track" cx="24" cy="24" r="21"/><circle id="restRing" class="ring-progress" cx="24" cy="24" r="21" stroke-dasharray="132" stroke-dashoffset="${132*(1-left/r.total)}"/></svg>${icon('timer')}</div><div><div class="timer-caption">${r.paused!=null?'REPOS EN PAUSE':r.kind==='exercise'?'REPOS ENTRE EXERCICES':'REPOS ENTRE SÉRIES'}</div><div class="timer-value" id="restValue" role="timer" aria-live="off">${timeStr(left)}</div></div><div class="timer-controls"><button data-action="restAdd" aria-label="Ajouter 30 secondes">+30 s</button><button data-action="restPause" aria-label="${r.paused!=null?'Reprendre':'Mettre en pause'} le repos">${icon(r.paused!=null?'play':'pause')}</button><button data-action="restSkip">Passer</button></div></div>`}
function tick(){syncCalendar(true);const d=state.draft;if(!d)return;if($('#elapsed'))$('#elapsed').textContent=timeStr((Date.now()-d.started)/1000);const r=d.rest;if(!r)return;const left=restSeconds();if(left<=0&&r.paused==null){d.rest=null;save();renderTimer();toast('Repos terminé. À toi de jouer !');beep();return}if($('#restValue'))$('#restValue').textContent=timeStr(left);$('#restRing')?.setAttribute('stroke-dashoffset',String(132*(1-left/r.total)));}
function beep(){if(!state.preferences.sound)return;try{audioCtx||=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.frequency.setValueAtTime(750,audioCtx.currentTime);g.gain.setValueAtTime(.07,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.35);o.start();o.stop(audioCtx.currentTime+.35)}catch{}}
function nextSuggestion(ex){const sets=ex.sets.filter(s=>s.done),inc=increment(ex.name);if(!sets.length)return null;const current=sets[0].load;if(sets.length<ex.sets.length)return{name:ex.name,load:current,reason:'Séance partielle · charge conservée',change:0};if(ex.manual){return{name:ex.name,load:current,reason:'Séance adaptée · charge conservée',change:0}}if(ex.method.includes('back-off')||ex.method==='Force')return{name:ex.name,load:current,reason:'Charge à suivre selon le bloc du cycle',change:0};if(sets.every(s=>s.reps>=s.max&&s.rir>=1))return{name:ex.name,load:round(current+inc,inc),reason:'Haut de fourchette atteint avec de la marge',change:inc};if(sets.some(s=>s.reps<s.min||s.rir===0))return{name:ex.name,load:Math.max(0,round(current-inc,inc)),reason:'Marge faible · proposition à ajuster',change:-inc};return{name:ex.name,load:current,reason:'Continue à progresser dans la fourchette',change:0}}
function celebrate(){if(!state.preferences.motion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const el=document.createElement('div');el.className='confetti';el.innerHTML=Array.from({length:28},()=>`<i style="--x:${Math.round(Math.random()*600-300)}px;--y:${Math.round(Math.random()*600-200)}px;--rot:${Math.round(Math.random()*720)}deg;animation-delay:${Math.random()*.2}s"></i>`).join('');document.body.append(el);setTimeout(()=>el.remove(),1500);}
const TEST_NAMES=['Développé couché','Développé militaire','Tractions lestées','Squat','Hack squat','Soulevé de terre roumain','Rowing lourd'];
function testModal(id){const current=state.tests.find(t=>t.id===id),t=current||{ex:TEST_NAMES[0],load:'',reps:'',rir:1,bw:state.profile.weight,date:localDate()};showModal(current?'Ajuster ton repère.':'Un nouveau repère.',`<form id="testForm" data-id="${current?esc(id):''}"><div class="field-grid"><div class="field" style="grid-column:1/-1"><label for="testEx">Exercice</label><select id="testEx" name="ex">${[...new Set([...TEST_NAMES,...state.tests.map(t=>t.ex)])].map(n=>`<option ${n===t.ex?'selected':''}>${esc(n)}</option>`).join('')}</select></div><div class="field"><label for="testLoad">Charge / lest · kg</label><input id="testLoad" name="load" type="number" step=".25" min="0" max="2000" value="${t.load}" required></div><div class="field"><label for="testReps">Répétitions</label><input id="testReps" name="reps" type="number" step="1" min="1" max="100" value="${t.reps}" required></div><div class="field"><label for="testRir">RIR · reps en réserve</label><input id="testRir" name="rir" type="number" step=".5" min="0" max="5" value="${t.rir}" required></div><div class="field"><label for="testDate">Date</label><input id="testDate" name="date" type="date" value="${t.date||localDate()}" required></div><div class="field" style="grid-column:1/-1"><label for="testBw">Poids du corps · kg (tractions)</label><input id="testBw" name="bw" type="number" min="1" max="500" step=".1" value="${t.bw||state.profile.weight}" required></div></div><div class="note">${icon('info')}e1RM = charge × (1 + reps / 30). Pour les tractions, l’estimation comprend le poids du corps et le lest. Le RIR est enregistré séparément.</div><button type="submit" class="btn btn-primary btn-wide" style="margin-top:23px">${icon('check')}Enregistrer la référence</button></form>`);}
function workingModal(name){const names=[...new Set(program.flatMap(p=>p.ex.map(e=>e.name)))],current=Object.hasOwn(state.workLoads,name);showModal('Régler une charge de travail.',`<form id="workingForm"><div class="field"><label for="workingEx">Exercice</label><select id="workingEx" name="ex">${names.map(n=>`<option ${n===name?'selected':''}>${esc(n)}</option>`).join('')}</select></div><div class="spacer"></div><label for="workingLoad">Charge de travail · kg</label><input id="workingLoad" name="load" type="number" step=".25" min="0" max="2000" value="${current?state.workLoads[name]:''}" required><button type="submit" class="btn btn-primary btn-wide" style="margin-top:23px">Enregistrer la charge</button></form>`);}
function helpModal(){showModal('Les bons repères.',`<div class="stack"><div><h3 style="font-size:16px">RIR : ce qu’il reste dans le moteur.</h3><p class="small muted" style="margin-top:8px">Un RIR de 2 signifie que tu estimes pouvoir faire encore 2 répétitions propres. Un RIR de 0 signifie aucune répétition en réserve.</p></div><div><h3 style="font-size:16px">e1RM : une estimation, pas une charge à tenter.</h3><p class="small muted" style="margin-top:8px">Calcul Epley : charge × (1 + reps / 30), sans ajouter le RIR. Il sert de repère pour comparer tes efforts. Pour les tractions, le résultat comprend le poids du corps.</p></div><div><h3 style="font-size:16px">Superset : deux exercices enchaînés.</h3><p class="small muted" style="margin-top:8px">Après la première série, l’app te propose l’exercice associé. Le repos démarre une fois la paire terminée.</p></div><div><h3 style="font-size:16px">Top set & back-off.</h3><p class="small muted" style="margin-top:8px">Une première série plus lourde, puis des séries avec une charge allégée. Les charges et objectifs sont indiqués séparément.</p></div><div><h3 style="font-size:16px">La progression des charges.</h3><p class="small muted" style="margin-top:8px">Une hausse est proposée si toutes les séries atteignent le haut de la fourchette avec au moins 1 rep en réserve. Une séance partielle conserve la charge. Le bloc force recalcule ses objectifs depuis tes tests.</p></div></div>`,[{label:'Compris',fn:closeModal}]);}
function exportData(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download='muscu-coach-'+localDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sauvegarde exportée.');}
async function importData(file){if(!file)return;try{if(file.size>5000000)throw Error('too large');const imported=normalise(JSON.parse(await file.text()));confirmDialog('Importer ce carnet ?',`${imported.tests.length} référence${imported.tests.length>1?'s':''} et ${imported.history.length} séance${imported.history.length>1?'s':''} seront chargées. Tes données actuelles seront remplacées. Tu peux les exporter avant d’importer.`,()=>{state=imported;save();render();toast('Carnet importé avec succès.');},'Importer')}catch{toast('Fichier invalide. Choisis une sauvegarde Muscu Coach V2 ou V3.')}$('#backupInput').value=''}
function chooseWeek(w){confirmDialog('Passer en semaine '+w+' ?',phase(w).desc,()=>{state.profile.week=w;previewWeek=w||1;save();render();toast('Semaine du cycle mise à jour.')},'Choisir cette semaine')}
function action(value){const split=value.indexOf(':'),cmd=split<0?value:value.slice(0,split),arg=split<0?'':value.slice(split+1);switch(cmd){
case 'today':selectionMode='auto';selectedDay=todayPlanDay();render();break;case 'chooseSession':navigate('workout');break;case 'adapt':adaptModal();break;case 'editPlan':planEditorModal(+arg,previewWeek);break;case 'editCurrentPlan':planEditorModal(+arg,state.profile.week);break;case 'planAdd':planExerciseEditor(-1);break;case 'planEdit':planExerciseEditor(+arg);break;case 'planMove':{const [i,delta]=arg.split(',').map(Number);movePlannedExercise(i,delta);break}case 'planRemove':removePlannedExercise(+arg);break;case 'planReset':{const [w,d]=arg.split(',').map(Number);confirmDialog('Réinitialiser cette séance ?','Tes personnalisations de cette séance seront supprimées. L’historique déjà enregistré ne change pas.',()=>{resetPlanOverride(w,d);planEditorModal(d,w)},'Réinitialiser');break}case 'addExercise':exerciseEditor(-1);break;case 'swapExercise':exerciseEditor(+arg);break;case 'removeExercise':removeExercise(+arg);break;case 'addSet':changeSetCount(1);break;case 'removeSet':changeSetCount(-1);break;case 'exerciseMemory':exerciseHistoryModal(arg||state.draft.exercises[state.draft.index].name);break;case 'exerciseNote':exerciseNoteModal(arg||state.draft.exercises[state.draft.index].name);break;case 'showRecords':progressMode='records';navigate('progress');break;case 'closeModal':closeModal();break;case 'help':helpModal();break;
case 'showRefs':progressMode='tests';navigate('progress');break;case 'showHistory':progressMode='history';navigate('progress');break;case 'showCycle':programMode='cycle';navigate('program');break;
case 'selectDay':selectedDay=+arg;selectionMode='manual';render();break;case 'restInfo':showRestDay(+arg);break;
case 'programMode':programMode=arg;render();break;case 'preview':previewWeek=+arg;programMode='sessions';render();break;case 'setWeek':chooseWeek(+arg);break;
case 'organizeWeek':organizeWeekModal(previewWeek);break;case 'resetWeek':resetWeekDays(+arg);closeModal();break;case 'showRecap':showSessionRecap(arg);break;case 'repeatResult':repeatResult(arg);break;
case 'start':startWorkout(+arg);break;case 'startPreview':startWorkout(+arg,previewWeek);break;case 'resume':navigate('workout');requestWakeLock();break;
case 'exercise':setExercise(+arg);break;case 'check':toggleSet(+arg);break;case 'finish':finishWorkout();break;
case 'discard':confirmDialog('Abandonner cette séance ?','Les séries de cette séance ne seront pas ajoutées à l’historique.',()=>{state.draft=null;save();releaseWake();navigate('home')},'Abandonner');break;
case 'copyLoad':{const e=state.draft.exercises[state.draft.index];const first=e.sets[0].load;if(first===0&&!/Tractions|dips/i.test(e.name)){toast('Renseigne d’abord la première charge.');break}e.sets.forEach(s=>{if(!s.done)s.load=first});save();render();toast('Charge copiée sur les séries restantes.');break}
case 'exerciseInfo':{const e=state.draft.exercises[state.draft.index];showModal(e.name,`<div class="stack"><div class="note"><b>${esc(e.method)}</b><br>${e.sets.map((s,i)=>'Série '+(i+1)+' : '+s.min+'–'+s.max+' reps · RIR '+s.rir+(s.label!=='Travail'?' · '+s.label:'')).join('<br>')}</div><p class="small muted">Tempo : ${e.tempo}. Dans l’ordre : descente, pause basse, montée, pause haute. X désigne une intention de montée rapide et contrôlée.</p><p class="small muted">Les charges proposées restent ajustables. Les charges des haltères correspondent à un haltère, et celles des tractions au lest ajouté.</p></div>`,[{label:'Retour à ma séance',fn:closeModal}]);break}
case 'restStart':startRest();break;case 'restSkip':if(state.draft){state.draft.rest=null;save();renderTimer()}break;
case 'restAdd':{const r=state.draft?.rest;if(r){r.total+=30;if(r.paused!=null)r.paused+=30;else r.end+=30000;save();renderTimer()}break}
case 'restPause':{const r=state.draft?.rest;if(r){if(r.paused!=null){r.end=Date.now()+r.paused*1000;r.paused=null}else r.paused=restSeconds();save();renderTimer()}break}
case 'restSettings':{const e=state.draft.exercises[state.draft.index];showModal('Ton temps de repos.',`<label for="restInput">Secondes entre les séries</label><input id="restInput" type="number" min="15" max="900" step="15" value="${e.rest}"><label for="exerciseRestInput">Secondes entre les exercices</label><input id="exerciseRestInput" type="number" min="15" max="900" step="15" value="${exerciseRestDuration(e)}"><div class="note">Entre exercices : une minute de plus par défaut. Ton réglage est conservé pour les prochaines séances. Pour un superset, le repos long commence après toutes les séries des deux mouvements. Aucun repos automatique après la dernière série de la séance.</div>`,[{label:'Enregistrer',fn:()=>{const n=+$('#restInput').value;if(!Number.isFinite(n)||n<15||n>900){toast('Choisis entre 15 et 900 secondes.');return}const between=+$('#exerciseRestInput').value;if(!Number.isFinite(between)||between<15||between>900){toast('Choisis entre 15 et 900 secondes entre exercices.');return}e.rest=Math.round(n);state.preferences.exerciseRest=Math.round(between);save();closeModal();render()}}]);break}
case 'progressMode':progressMode=arg;render();break;case 'chartPoint':{const p=progressPoints(chartExercise)[+arg];if(p&&$('#chartDetail'))$('#chartDetail').textContent=`${p.type} · ${dateFr(p.date)} · e1RM ${fmt(p.value)} kg`;break}
case 'test':testModal(arg);break;case 'deleteTest':confirmDialog('Supprimer cette référence ?','Les charges calculées utiliseront tes autres références disponibles.',()=>{state.tests=state.tests.filter(t=>t.id!==arg);save();render();toast('Référence supprimée.')},'Supprimer');break;
case 'working':workingModal(arg);break;case 'deleteHistory':confirmDialog('Supprimer cette séance ?','Les séries seront retirées de l’historique et des graphiques. Tes charges de travail actuelles seront conservées.',()=>{state.history=state.history.filter(h=>h.id!==arg);save();render()},'Supprimer');break;
case 'toggle':state.preferences[arg]=!state.preferences[arg];save();if(arg==='sound'&&state.preferences.sound)beep();render();break;
case 'export':exportData();break;case 'import':$('#backupInput').click();break;
case 'reset':confirmDialog('Repartir de zéro ?','Ton historique, tes réglages et tes références personnalisées seront effacés de cette version. Exporte un carnet si tu veux les conserver.',()=>{state=clone(BASELINE);save();releaseWake();closeModal();navigate('home')},'Réinitialiser');break;
}}
document.addEventListener('click',ev=>{const modalBtn=ev.target.closest('[data-modal-action]');if(modalBtn){modalActions[modalBtn.dataset.modalAction]?.();return}const actionBtn=ev.target.closest('[data-action]');if(actionBtn){action(actionBtn.dataset.action);return}const nav=ev.target.closest('[data-tab]');if(nav){navigate(nav.dataset.tab);return}const brand=ev.target.closest('a[href="#home"]');if(brand){ev.preventDefault();navigate('home')}if(ev.target.classList.contains('modal-backdrop'))closeModal()});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&$('.modal')){closeModal();return}if(ev.target.matches('.chart-point')&&['Enter',' '].includes(ev.key)){ev.preventDefault();action(ev.target.dataset.action)}if(ev.key==='Tab'&&$('.modal')){const items=[...$('.modal').querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled);if(ev.shiftKey&&document.activeElement===items[0]){ev.preventDefault();items.at(-1).focus()}else if(!ev.shiftKey&&document.activeElement===items.at(-1)){ev.preventDefault();items[0].focus()}}});
document.addEventListener('input',ev=>{const el=ev.target;if(el.matches('[data-set][data-field]')&&state.draft){const s=state.draft.exercises[state.draft.index].sets[+el.dataset.set],val=Number(el.value);if(el.value!==''&&Number.isFinite(val)&&val>=0&&val<=(el.dataset.field==='load'?2000:el.dataset.field==='reps'?100:5)){s[el.dataset.field]=val;save()}}});
document.addEventListener('change',ev=>{const el=ev.target;if(el.dataset.input==='chooseDay'){selectedDay=+el.value;selectionMode='manual';render()}if(el.dataset.input==='chartExercise'){chartExercise=el.value;render()}if(el.dataset.input==='assignDay'){setDayAssignment(previewWeek,+el.dataset.day,el.value==='rest'?'rest':+el.value)}if(el.id==='backupInput')importData(el.files[0]);});
document.addEventListener('submit',ev=>{const form=ev.target;ev.preventDefault();if(!form.reportValidity())return;const f=new FormData(form);if(form.id==='exerciseEditForm'){saveExerciseEdit(form,f);return}if(form.id==='planExerciseEditForm'){savePlanExerciseEdit(form,f);return}if(form.id==='exerciseNoteForm'){saveExerciseNote(form,f);return}if(form.id==='profileForm'){state.profile={...state.profile,name:String(f.get('name')).trim()||'Joris',weight:Number(f.get('weight')),week:Number(f.get('week'))};previewWeek=state.profile.week||1;save();render();toast('Réglages enregistrés.')}if(form.id==='testForm'){const t={id:form.dataset.id||uid(),ex:String(f.get('ex')),load:Number(f.get('load')),reps:Number(f.get('reps')),rir:Number(f.get('rir')),bw:Number(f.get('bw')),date:String(f.get('date'))};if(form.dataset.id)state.tests=state.tests.map(old=>old.id===t.id?t:old);else state.tests.push(t);save();closeModal();render();toast('Référence enregistrée.')}if(form.id==='workingForm'){state.workLoads[String(f.get('ex'))]=Number(f.get('load'));save();closeModal();render();toast('Charge de travail mise à jour.')}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){tick();requestWakeLock()}});window.addEventListener('pagehide',()=>{if(state.draft)save()});
// Calendar follows the device's local day. The selected training template is a separate concept.
function todayPlanDay(){const day=new Date().getDay();return day===0?6:day-1}
function fullDateLabel(date=new Date()){const label=date.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'});return label[0].toUpperCase()+label.slice(1)}
function syncCalendar(shouldRender){const now=localDate();if(now===calendarKey)return;calendarKey=now;selectionMode='auto';selectedDay=todayPlanDay();if(shouldRender){updateShell();if((tab==='home'||(tab==='workout'&&!state.draft))&&!$('.modal'))render()}}
function thisWeekDates(){const monday=new Date();monday.setHours(12,0,0,0);monday.setDate(monday.getDate()-((monday.getDay()+6)%7));return Array.from({length:7},(_,i)=>{const d=new Date(monday);d.setDate(d.getDate()+i);return d})}
function prettySessionTitle(name){const parts=name.split(' + ');return esc(parts[0])+(parts.length>1?'<br><span>+ '+esc(parts.slice(1).join(' + '))+'</span>':'')}
function homeContext(){const active=state.draft,day=active?active.day:selectionMode==='auto'?todayPlanDay():selectedDay,w=active?active.week:state.profile.week,rest=!active&&templateForDay(day,w)===null,completed=!active&&selectionMode==='auto'?state.history.filter(h=>localDate(new Date(h.date))===localDate()&&h.week===state.profile.week).sort((a,b)=>new Date(a.date)-new Date(b.date)).at(-1):null;return{active,day,rest,completed}}
function homeHeroHTML(){const {active,day,rest,completed}=homeContext(),tpl=active?program[active.templateDay]:program[templateForDay(day,state.profile.week)],manual=selectionMode==='manual'&&!active,plan=active?.exercises||planFor(day,state.profile.week),wk=weeklyHistory(),dates=thisWeekDates(),completedDates=new Set(wk.map(h=>localDate(new Date(h.date))));let label=active?'SÉANCE EN COURS':rest?(manual?'JOUR DE REPOS':'AUJOURD’HUI · RÉCUPÉRATION'):manual?'SÉANCE SÉLECTIONNÉE':completed?'SÉANCE DU JOUR TERMINÉE':'SÉANCE DU JOUR';const badge=active?`Commencée le ${dateFr(new Date(active.started).toISOString())}`:rest?WEEKDAYS[day]:manual?`${WEEKDAYS[day]}`:`${WEEKDAYS[day]} ${new Date().getDate()}`;
return `<div class="hero-grid stagger">${completed?completedHomeHTML(completed):`<section class="card session-card ${rest?'rest-card':''}"><span class="session-number" aria-hidden="true">${String(day+1).padStart(2,'0')}</span><div class="row between"><span class="eyebrow orange" id="sessionContext">${label}</span><span class="pill" id="sessionDay">${badge}</span></div><h2 class="session-title">${rest?'RÉCUPÈRE.<br><span>REVIENS FORT.</span>':prettySessionTitle(tpl.name)}</h2>${rest?`<p class="rest-description">${WEEKDAYS[day]} est ton jour de repos pour cette semaine.<br>Change l’organisation quand tu veux depuis l’onglet Programme.</p>`:`<div class="session-meta"><span>${icon('dumbbell')}${plan.length} exercices</span><span>${icon('list')}${active?draftStats().done+' / '+draftStats().total:completed?completed.sets.length:plan.reduce((n,e)=>n+e.sets.length,0)} séries${completed?' validées':''}</span></div>`}<div class="session-footer">${btn(active?'Reprendre ma séance':rest?'Voir les séances':completed?'Voir mon bilan':manual?'Démarrer cette séance':'C’est parti',active?'resume':rest?'chooseSession':completed?'showHistory':'start:'+day,'primary',completed?'check':'arrow')}</div>${manual?`<button class="link-btn today-return" data-action="today">${icon('calendar')}Revenir à aujourd’hui · ${new Date().toLocaleDateString('fr-FR',{weekday:'long'})}</button>`:active?`<p class="micro muted" style="margin-top:14px">${WEEKDAYS[day].toLowerCase()} · tes séries en cours sont conservées.</p>`:''}</section>`}<section class="card week-card"><div class="row between"><h2>Cette semaine</h2><span class="pill">Objectif 6 séances</span></div><div class="ring-wrap"><svg viewBox="0 0 192 192" role="img" aria-label="${wk.length} séances sur un objectif de 6"><circle class="ring-track" cx="96" cy="96" r="73"/><circle class="ring-progress" cx="96" cy="96" r="73" stroke-dasharray="459" stroke-dashoffset="${459*(1-Math.min(1,wk.length/6))}"/></svg><div class="ring-inner"><b>${wk.length}<small> / 6</small></b><span>SÉANCES FAITES</span></div></div><div class="week-strip">${dates.map((date,i)=>{const isRest=templateForDay(i,state.profile.week)===null;return `<button class="week-dot ${localDate(date)===localDate()?'today':''} ${completedDates.has(localDate(date))?'completed':''} ${isRest?'rest':''} ${manual&&i===selectedDay?'chosen':''}" data-action="${isRest?'restInfo:'+i:'selectDay:'+i}" aria-label="${fullDateLabel(date)}${isRest?' : récupération':''}" ${localDate(date)===localDate()?'aria-current="date"':''}><span>${date.getDate()}</span><em>${['L','M','M','J','V','S','D'][i]}${completedDates.has(localDate(date))?' ✓':''}</em></button>`}).join('')}</div></section></div>`}
function weekSummaryExtras(){const latest=state.history.at(-1),records=latest?.records||[];if(!records.length)return '';return `<button class="latest-record" data-action="showRecords">${icon('trophy')}<span><b>${records.length} record${records.length>1?'s':''} dans ta dernière séance</b><small>${records.map(r=>esc(r.name)).join(' · ')}</small></span>${icon('chevron')}</button>`}
function showRestDay(day){showModal(WEEKDAYS[day]+' · récupération.',`<p class="small muted">Pas de séance programmée ${WEEKDAYS[day].toLowerCase()} pour cette semaine. Tu peux consulter le programme, choisir une séance manuellement, ou réorganiser ta semaine depuis l’onglet Programme.</p>`,[{label:'Fermer',kind:'outline',fn:closeModal},{label:'Voir les séances',fn:()=>{closeModal();navigate('workout')}}])}
function currentExercise(){return state.draft?.exercises[state.draft.index]}
function exerciseMemoryHTML(ex){const note=state.exerciseNotes?.[ex.name],prior=lastSets(ex.name);return `<div class="exercise-memory"><div class="row between wrap"><button class="link-btn" data-action="exerciseMemory">${icon('history')}${prior.length?'Ma dernière séance':'Historique du mouvement'}</button><button class="link-btn" data-action="exerciseNote">${icon('edit')}${note?'Modifier ma note':'Ajouter un repère'}</button></div>${note?`<p class="exercise-note">${esc(note)}</p>`:''}</div>`}
function exerciseHistoryModal(name){const sessions=[...state.history].reverse().filter(h=>h.sets.some(s=>s.name===name)).slice(0,6);const prior=sessions[0]?.sets.filter(s=>s.name===name)||[],record=recordFor(name);showModal(name,`${record?`<div class="exercise-record-head">${icon('trophy')}<div><small>MEILLEURE CHARGE EN SÉANCE</small><b>${fmt(record.load)} kg <span>× ${record.reps} reps</span></b></div></div>`:''}${sessions.length?sessions.map((h,i)=>`<div class="exercise-history-block"><div class="row between"><b>${dateFr(h.date)}</b><span class="micro muted">${i===0?'DERNIÈRE SÉANCE':esc(h.name)}</span></div><div class="past-set-grid"><span>Série</span><span>Charge</span><span>Reps</span><span>RIR</span>${h.sets.filter(s=>s.name===name).map((s,j)=>`<b>${j+1}</b><strong>${fmt(s.load)} kg</strong><b>${s.reps}</b><b>${s.rir}</b>`).join('')}</div></div>`).join(''):empty('history','Aucune séance enregistrée sur ce mouvement.','Tes séries apparaîtront ici après avoir terminé et enregistré ta séance.')}`,prior.length&&currentExercise()?.name===name?[{label:'Fermer',kind:'outline',fn:closeModal},{label:'Reprendre ces charges',fn:()=>{const e=currentExercise();e.sets.forEach((s,i)=>{if(!s.done)s.load=(prior[i]||prior.at(-1)).load});e.calibrated=true;save();closeModal();render();toast('Charges reprises. Les objectifs de reps sont conservés.')}}]:[{label:'Fermer',fn:closeModal}]);}
function exerciseNoteModal(name){showModal('Ton repère sur ce mouvement.',`<form id="exerciseNoteForm" data-exercise="${esc(name)}"><p class="small muted" style="margin-bottom:16px">${esc(name)}</p><label for="exerciseNoteInput">Réglage, placement, détail à retrouver</label><textarea id="exerciseNoteInput" name="note" rows="4" maxlength="1000" placeholder="Siège au cran 4, prise neutre…">${esc(state.exerciseNotes?.[name]||'')}</textarea><p class="micro muted" style="margin-top:12px">Cette note sera retrouvée à chaque séance sur ce mouvement.</p><button type="submit" class="btn btn-primary btn-wide" style="margin-top:20px">Enregistrer mon repère</button></form>`)}
function saveExerciseNote(form,f){state.exerciseNotes||={};const name=form.dataset.exercise,value=String(f.get('note')).trim();if(value)Object.defineProperty(state.exerciseNotes,name,{value,writable:true,configurable:true,enumerable:true});else delete state.exerciseNotes[name];save();closeModal();render();toast(value?'Repère enregistré.':'Repère supprimé.')}
function allExerciseNames(){return [...new Set([...program.flatMap(p=>p.ex.map(e=>e.name)),...Object.values(state.planOverrides||{}).flatMap(week=>Object.values(week||{}).flatMap(list=>Array.isArray(list)?list.map(e=>e.name):[]))])].sort((a,b)=>a.localeCompare(b,'fr'))}
function planEditorModal(day,w){const t=templateForDay(day,w);if(t===null){toast('Aucune séance programmée ce jour.');return}planEditContext={day,w};const list=planFor(day,w),custom=hasPlanOverride(w,day);showModal('Modifier '+program[t].name+'.',`<p class="small muted" style="margin-bottom:15px">Ajoute, remplace, supprime ou déplace les exercices maintenant. Rien ne démarre : le chrono partira seulement quand tu lanceras la séance.</p><div class="adapt-list">${list.map((e,i)=>`<div class="adapt-row"><span class="adapt-number">${String(i+1).padStart(2,'0')}</span><div class="adapt-name"><b>${esc(e.name)}</b><small>${e.sets.length} séries · ${esc(e.reps)} reps · RIR ${e.rir}</small></div><div class="row"><button class="icon-btn" data-action="planMove:${i},-1" ${i===0?'disabled':''} aria-label="Monter ${esc(e.name)}"><span aria-hidden="true">↑</span></button><button class="icon-btn" data-action="planMove:${i},1" ${i===list.length-1?'disabled':''} aria-label="Descendre ${esc(e.name)}"><span aria-hidden="true">↓</span></button><button class="icon-btn" data-action="planEdit:${i}" aria-label="Modifier ${esc(e.name)}">${icon('edit')}</button><button class="icon-btn" data-action="planRemove:${i}" ${list.length<=1?'disabled':''} aria-label="Retirer ${esc(e.name)}">${icon('trash')}</button></div></div>`).join('')}</div><button class="btn btn-outline btn-wide" data-action="planAdd" style="margin-top:18px">${icon('plus')}Ajouter un mouvement</button>${custom?`<button class="link-btn" data-action="planReset:${w},${day}" style="margin-top:16px">${icon('history')}Revenir au programme prévu</button>`:''}<p class="micro muted" style="margin-top:13px">Ces changements concernent la semaine ${w}, ${WEEKDAYS[day].toLowerCase()}. Ils sont enregistrés avant la séance et synchronisés avec ton carnet.</p>`,[{label:'Terminé',fn:closeModal}],true)}
function detachPlanSuperset(list,tag){if(!tag?.startsWith('superset'))return;list.forEach(e=>{if(e.tag===tag){e.tag='';e.method='Séries classiques';e.plannedCustom=true}})}
function movePlannedExercise(index,delta){if(!planEditContext||!Number.isInteger(index)||!Number.isInteger(delta)||!delta)return;const {day,w}=planEditContext,list=ensurePlanOverride(w,day),target=index+delta;if(index<0||index>=list.length||target<0||target>=list.length)return;detachPlanSuperset(list,list[index].tag);[list[index],list[target]]=[list[target],list[index]];save();render();planEditorModal(day,w)}
function removePlannedExercise(index){if(!planEditContext)return;const {day,w}=planEditContext,list=ensurePlanOverride(w,day),e=list[index];if(!e||list.length<=1)return;detachPlanSuperset(list,e.tag);list.splice(index,1);save();render();toast('Mouvement retiré de cette séance.');planEditorModal(day,w)}
function planExerciseEditor(index){if(!planEditContext)return;const {day,w}=planEditContext,list=planFor(day,w),old=index>=0?list[index]:null,names=allExerciseNames(),positionMax=old?list.length:list.length+1;showModal(old?'Modifier ce mouvement.':'Ajouter un mouvement.',`<form id="planExerciseEditForm" data-index="${index}"><label for="planExerciseName">Nom du mouvement</label><input id="planExerciseName" name="name" list="planExerciseSuggestions" value="${old?esc(old.name):''}" required maxlength="120" placeholder="Choisir ou écrire un mouvement" autocomplete="off"><datalist id="planExerciseSuggestions">${names.map(n=>`<option value="${esc(n)}"></option>`).join('')}</datalist><div class="field-grid" style="margin-top:18px"><div><label for="planSets">Séries</label><input id="planSets" name="sets" type="number" min="1" max="12" step="1" value="${old?.sets.length||3}" required></div><div><label for="planPosition">Position dans la séance</label><input id="planPosition" name="position" type="number" min="1" max="${positionMax}" step="1" value="${old?index+1:list.length+1}" required></div><div><label for="planLoad">Charge proposée · kg</label><input id="planLoad" name="load" type="number" min="0" max="2000" step=".25" value="${old?.load==null?'':old.load}" placeholder="Vide = à calibrer"></div><div><label for="planRir">RIR visé</label><input id="planRir" name="rir" type="number" min="0" max="5" step=".5" value="${old?.rir??2}" required></div><div><label for="planMin">Reps minimum</label><input id="planMin" name="min" type="number" min="1" max="100" step="1" value="${old?repRange(old.reps).min:8}" required></div><div><label for="planMax">Reps maximum</label><input id="planMax" name="max" type="number" min="1" max="100" step="1" value="${old?repRange(old.reps).max:12}" required></div><div style="grid-column:1/-1"><label for="planRest">Repos entre séries · secondes</label><input id="planRest" name="rest" type="number" min="15" max="900" step="15" value="${old?.rest||90}" required></div></div><label class="bodyweight-choice"><input type="checkbox" name="bodyweight" ${old?.allowZero?'checked':''}>Ce mouvement peut se faire sans charge ajoutée</label><div class="note">La charge peut rester vide : l’app te laissera la calibrer pendant la séance. La position choisie est enregistrée avant de démarrer.</div><button type="submit" class="btn btn-primary btn-wide" style="margin-top:20px">${old?'Enregistrer les modifications':'Ajouter à la séance'}</button></form>`)}
function savePlanExerciseEdit(form,f){if(!planEditContext)return;const {day,w}=planEditContext,index=Number(form.dataset.index),list=ensurePlanOverride(w,day),old=index>=0?list[index]:null,name=String(f.get('name')).trim(),sets=Number(f.get('sets')),position=Number(f.get('position')),loadRaw=String(f.get('load')??'').trim(),load=loadRaw===''?null:Number(loadRaw),min=Number(f.get('min')),max=Number(f.get('max')),rir=Number(f.get('rir')),rest=Number(f.get('rest'));if(!name||['__proto__','constructor','prototype'].includes(name)||name.length>120||!Number.isInteger(sets)||sets<1||sets>12||!Number.isInteger(position)||position<1||position>(old?list.length:list.length+1)||!Number.isInteger(min)||!Number.isInteger(max)||min<1||max>100||min>max||(load!==null&&(!Number.isFinite(load)||load<0||load>2000))||!Number.isFinite(rir)||rir<0||rir>5||!Number.isFinite(rest)||rest<15||rest>900){toast('Vérifie les objectifs du mouvement.');return}if(list.some((e,i)=>i!==index&&e.name===name)){toast('Ce mouvement est déjà dans cette séance.');return}if(old?.tag?.startsWith('superset'))detachPlanSuperset(list,old.tag);const allowZero=f.has('bodyweight'),e={name,sets:Array.from({length:sets},()=>({load,reps:max,rir,min,max,label:'Travail'})),reps:min+'–'+max,rir,tag:'',load,rest,tempo:'Contrôlé',method:'Séries personnalisées',calibrated:load!==null&&(load>0||allowZero),allowZero,plannedCustom:true};if(old){list.splice(index,1);const insertAt=Math.max(0,Math.min(list.length,position-1));list.splice(insertAt,0,e)}else{list.splice(Math.max(0,Math.min(list.length,position-1)),0,e)}save();closeModal();render();toast(old?'Mouvement modifié dans le programme.':'Mouvement ajouté au programme.');planEditorModal(day,w)}
function adaptModal(){const d=state.draft;if(!d)return;showModal('Adapte ta séance.',`<p class="small muted" style="margin-bottom:15px">Machine occupée, autre mouvement : ajuste cette séance. Ton programme de base reste disponible.</p><div class="adapt-list">${d.exercises.map((e,i)=>{const done=e.sets.filter(s=>s.done).length;return `<div class="adapt-row"><span class="adapt-number">${String(i+1).padStart(2,'0')}</span><div class="adapt-name"><b>${esc(e.name)}</b><small>${e.sets.length} séries${e.tag.startsWith('superset')?' · '+esc(e.method):''}${done?' · '+done+' validée'+(done>1?'s':''):''}</small></div><div class="row"><button class="icon-btn" data-action="swapExercise:${i}" ${done?'disabled':''} aria-label="Remplacer ${esc(e.name)}">${icon('edit')}</button><button class="icon-btn" data-action="removeExercise:${i}" ${done||d.exercises.length<=1?'disabled':''} aria-label="Retirer ${esc(e.name)}">${icon('trash')}</button></div></div>`}).join('')}</div><button class="btn btn-outline btn-wide" data-action="addExercise" style="margin-top:18px">${icon('plus')}Ajouter un mouvement</button><p class="micro muted" style="margin-top:13px">Un mouvement avec une série validée est conservé dans ta séance.</p>`,[{label:'Retour à ma séance',fn:closeModal}],true)}
function exerciseEditor(index){const d=state.draft;if(!d)return;const old=index>=0?d.exercises[index]:null;if(old?.sets.some(s=>s.done)){toast('Conserve ce mouvement : des séries sont déjà validées.');return}const names=[...new Set(program.flatMap(p=>p.ex.map(e=>e.name)))].sort((a,b)=>a.localeCompare(b,'fr'));showModal(old?'Choisir un autre mouvement.':'Ajouter un mouvement.',`<form id="exerciseEditForm" data-index="${index}"><label for="customExerciseName">Nom du mouvement</label><input id="customExerciseName" name="name" list="exerciseSuggestions" value="" required maxlength="120" placeholder="Choisir ou écrire un mouvement" autocomplete="off"><datalist id="exerciseSuggestions">${names.map(n=>`<option value="${esc(n)}"></option>`).join('')}</datalist><div class="field-grid" style="margin-top:18px"><div><label for="customSets">Séries</label><input id="customSets" name="sets" type="number" min="1" max="12" step="1" value="${old?.sets.length||3}" ${old?.tag.startsWith('superset')?'readonly':''} required></div><div><label for="customLoad">Charge / lest · kg</label><input id="customLoad" name="load" type="number" min="0" max="2000" step=".25" value="" required placeholder="À renseigner"></div><div><label for="customMin">Reps minimum</label><input id="customMin" name="min" type="number" min="1" max="100" step="1" value="${old?repRange(old.reps).min:8}" required></div><div><label for="customMax">Reps maximum</label><input id="customMax" name="max" type="number" min="1" max="100" step="1" value="${old?repRange(old.reps).max:12}" required></div><div><label for="customRir">RIR visé</label><input id="customRir" name="rir" type="number" min="0" max="5" step=".5" value="${old?.rir??2}" required></div><div><label for="customRest">Repos · secondes</label><input id="customRest" name="rest" type="number" min="15" max="900" step="1" value="${old?.rest||90}" required></div></div><label class="bodyweight-choice"><input type="checkbox" name="bodyweight">Ce mouvement peut se faire sans charge ajoutée</label><div class="note">${old?.tag.startsWith('superset')?'Le mouvement garde sa place dans le superset. Le nombre de séries reste identique à celui du partenaire.':'Les objectifs sont ceux que tu choisis pour cette séance.'}</div><button type="submit" class="btn btn-primary btn-wide" style="margin-top:20px">${old?'Remplacer le mouvement':'Ajouter à ma séance'}</button></form>`)}
function saveExerciseEdit(form,f){const d=state.draft;if(!d)return;const index=Number(form.dataset.index),old=index>=0?d.exercises[index]:null;if(old?.sets.some(s=>s.done)){toast('Ce mouvement contient une série validée.');return}const name=String(f.get('name')).trim(),sets=Number(f.get('sets')),load=Number(f.get('load')),min=Number(f.get('min')),max=Number(f.get('max')),rir=Number(f.get('rir')),rest=Number(f.get('rest'));
if(!name||['__proto__','constructor','prototype'].includes(name)||name.length>120||!Number.isInteger(sets)||sets<1||sets>12||!Number.isInteger(min)||!Number.isInteger(max)||min<1||max>100||min>max||!Number.isFinite(load)||load<0||load>2000||!Number.isFinite(rir)||rir<0||rir>5||!Number.isFinite(rest)||rest<15||rest>900){toast('Vérifie les objectifs du mouvement.');return}if(d.exercises.some((e,i)=>i!==index&&e.name===name)){toast('Ce mouvement est déjà dans ta séance.');return}if(old?.tag.startsWith('superset')&&sets!==old.sets.length){toast('Conserve le même nombre de séries pour la paire.');return}const tag=old?.tag.startsWith('superset')?old.tag:'',e={name,sets:Array.from({length:sets},()=>({load,reps:max,rir,min,max,label:'Travail',done:false})),reps:min+'–'+max,rir,tag,load,rest,tempo:'Contrôlé',method:tag?tag.replace('superset','Superset'):'Séries personnalisées',calibrated:load>0||f.has('bodyweight'),allowZero:f.has('bodyweight'),manual:true};if(old){d.exercises[index]=e;d.index=index}else{d.exercises.push(e);d.index=d.exercises.length-1}d.rest=null;save();closeModal();render();toast(old?'Mouvement remplacé pour cette séance.':'Mouvement ajouté.');}
function removeExercise(index){const d=state.draft,e=d?.exercises[index];if(!e||e.sets.some(s=>s.done)||d.exercises.length<=1)return;confirmDialog('Retirer ce mouvement ?',`<b>${esc(e.name)}</b> sera retiré de cette séance.${e.tag.startsWith('superset')?' Son partenaire continuera en séries classiques.':''}`,()=>{const active=d.exercises[d.index];d.exercises.splice(index,1);d.exercises.forEach(x=>{if(e.tag.startsWith('superset')&&x.tag===e.tag){x.tag='';x.method='Séries classiques';x.manual=true}});d.index=Math.max(0,d.exercises.indexOf(active));d.rest=null;save();render();adaptModal()},'Retirer')}
function changeSetCount(delta){const d=state.draft,e=currentExercise();if(!e)return;const pair=e.tag.startsWith('superset')?d.exercises.filter(x=>x.tag===e.tag):[e];if(delta>0){if(pair.some(x=>x.sets.length>=12)){toast('Maximum 12 séries par mouvement.');return}pair.forEach(x=>{const last=x.sets.at(-1);x.sets.push({...last,done:false,label:'Ajoutée'});x.manual=true})}else{if(pair.some(x=>x.sets.length<=1||x.sets.at(-1).done)){toast('Seule une dernière série non validée peut être retirée.');return}pair.forEach(x=>{x.sets.pop();x.manual=true})}save();render();toast(pair.length>1?(delta>0?'Une paire de séries ajoutée au superset.':'Une paire de séries retirée.'):(delta>0?'Une série ajoutée.':'Une série retirée.'))}
function recordFor(name,history=state.history){let best=null;for(const h of history)for(const s of h.sets){if(s.name!==name)continue;if(!best||s.load>best.load||(s.load===best.load&&s.reps>best.reps))best={name,load:s.load,reps:s.reps,date:h.date,session:h.id}}return best}
function allRecords(){return [...new Set(state.history.flatMap(h=>h.sets.map(s=>s.name)))].map(n=>recordFor(n)).sort((a,b)=>new Date(b.date)-new Date(a.date)||a.name.localeCompare(b.name,'fr'))}
function detectRecords(sets,history){const records=[];for(const name of new Set(sets.map(s=>s.name))){const previous=recordFor(name,history);if(!previous)continue;const best=sets.filter(s=>s.name===name).sort((a,b)=>b.load-a.load||b.reps-a.reps)[0];if(best.load>previous.load||(best.load===previous.load&&best.reps>previous.reps))records.push({name,load:best.load,reps:best.reps,previousLoad:previous.load,previousReps:previous.reps})}return records}
function recordCelebrationHTML(records){return records.length?`<section class="record-celebration"><div class="row">${icon('trophy')}<b>${records.length} nouveau${records.length>1?'x':''} record${records.length>1?'s':''} en séance</b></div>${records.map(r=>`<div class="row between"><span>${esc(r.name)}</span><strong>${fmt(r.load)} kg × ${r.reps}</strong></div>`).join('')}</section>`:''}
function recordsView(){const records=allRecords();return `<section class="card"><div class="row between card-head"><h2>Tes meilleures séries.</h2><span class="pill orange">${icon('trophy')}${records.length} mouvement${records.length>1?'s':''}</span></div><p class="small muted" style="margin-top:12px">La plus lourde charge validée en séance. À charge égale, le meilleur nombre de répétitions.</p>${records.length?`<div class="records-grid">${records.map(r=>`<button class="record-card" data-action="exerciseMemory:${esc(r.name)}"><div class="row between">${icon('trophy')}<small>${dateFr(r.date)}</small></div><h3>${esc(r.name)}</h3><b>${fmt(r.load)}<small> kg</small></b><p>× ${r.reps} répétitions${r.name==='Tractions lestées'?' · lest ajouté':''}</p><span class="record-open">Voir mes séries ${icon('up')}</span></button>`).join('')}</div>`:empty('trophy','Tes records se construisent à la salle.','Enregistre une première séance pour créer tes repères. Les séances suivantes pourront battre ces références.')}<div class="note" style="margin-top:20px">Ces records viennent de tes séries réellement enregistrées. Ils sont séparés des tests de force et des estimations de 1RM.</div></section>`}

// One presentation of saved results, shared by cards, history and the final recap.
// Counts always come from recorded sets; old backups without targets stay neutral.
function resultStats(h){
 const sets=Array.isArray(h.sets)?h.sets:[],done=sets.length;
 const raw=Number(h.completion?.total),known=Number.isInteger(raw)&&raw>0&&raw>=done;
 const total=known?raw:null,full=known&&done===total;
 return {done,total,full,ratio:known?done/total:null,remaining:known?total-done:null,
  exercises:new Set(sets.map(s=>s.name)).size,volume:workload(sets),reps:sets.reduce((n,s)=>n+s.reps,0),
  minutes:h.duration>0?Math.max(1,Math.round(h.duration/60)):null,
  label:full?'Complète':known?'Partielle':'Enregistrée'};
}
function resultGroups(h){
 const actual=[...new Set(h.sets.map(s=>s.name))],metadata=Array.isArray(h.exercises)?h.exercises:[];
 const names=[...new Set([...metadata.map(e=>e.name),...actual])];
 return names.map(name=>{const sets=h.sets.filter(s=>s.name===name),e=metadata.find(e=>e.name===name),total=Number.isInteger(e?.total)&&e.total>=sets.length?e.total:null;return {name,sets,total}});
}
function resultDate(h){return new Date(h.date).toLocaleDateString('fr-FR',{day:'numeric',month:'long'})}
function resultVolume(h){const n=resultStats(h).volume;return n>=1000?{value:fmt(n/1000,2),unit:'t'}:{value:fmt(n,0),unit:'kg'}}
function resultRing(h){const s=resultStats(h),n=s.ratio==null?null:Math.round(s.ratio*100);return `<div class="result-ring ${s.full?'is-full':''}" role="img" aria-label="${s.total?s.done+' séries validées sur '+s.total:s.done+' séries enregistrées'}"><svg viewBox="0 0 80 80" aria-hidden="true"><circle class="result-ring-track" cx="40" cy="40" r="34"/><circle class="result-ring-fill" cx="40" cy="40" r="34" stroke-dasharray="213.63" stroke-dashoffset="${s.ratio==null?0:213.63*(1-s.ratio)}"/></svg><span>${s.full?icon('check'):n==null?icon('check'):`<b>${n}<small>%</small></b>`}</span></div>`}
function resultMetrics(h){const s=resultStats(h),v=resultVolume(h);return `<div class="result-metrics"><div><span>${icon('list')}Séries validées</span><strong>${s.done}${s.total?`<small> / ${s.total}</small>`:''}</strong></div><div><span>${icon('clock')}Durée</span><strong>${s.minutes??'—'}${s.minutes?'<small> min</small>':''}</strong></div><div><span>${icon('weight')}Volume saisi</span><strong>${v.value}<small> ${v.unit}</small></strong></div></div>`}
function compactResults(h){return `<div class="result-exercise-list">${resultGroups(h).filter(e=>e.sets.length).map(e=>{const best=[...e.sets].sort((a,b)=>b.load-a.load||b.reps-a.reps)[0];return `<div class="result-exercise"><span class="result-tick">${icon('check')}</span><div><b>${esc(e.name)}</b><p>${e.sets.length} série${e.sets.length>1?'s':''} validée${e.sets.length>1?'s':''}${e.total?' / '+e.total:''}</p></div><span class="result-best">${fmt(best.load)}<small> kg</small><em>× ${best.reps} reps</em></span></div>`}).join('')}</div>`}
function resultProgress(h){const s=resultStats(h);return `<div class="result-progress"><div><span>${s.full?'Tout le programme a été validé.':s.total?`${s.remaining} série${s.remaining>1?'s':''} non validée${s.remaining>1?'s':''}`:'Objectif initial non renseigné'}</span><b>${s.label}</b></div>${s.total?`<div class="result-track"><i style="width:${s.ratio*100}%"></i></div>`:''}</div>`}
function resultStatus(h){const s=resultStats(h);return `<span class="result-status ${s.full?'is-full':''}">${icon('check')}SÉANCE ENREGISTRÉE</span>`}
function latestDayResult(day,w){const t=templateForDay(day,w);if(t===null)return null;return state.history.filter(h=>h.week===w&&h.day===day&&(Number.isInteger(h.templateDay)?h.templateDay===t:h.name===program[t].name)).sort((a,b)=>new Date(b.date)-new Date(a.date))[0]||null}
function completedDayHTML(h,day,w){const s=resultStats(h);return `<details class="day-card result-card ${s.full?'is-full':''}" data-result-id="${esc(h.id)}"><summary><div class="result-top"><span class="eyebrow">${WEEKDAYS[day]}</span>${resultStatus(h)}</div><div class="result-title-row"><div><p class="result-caption">BILAN DU ${resultDate(h)}</p><h2 class="day-title">${esc(h.name)}</h2></div>${resultRing(h)}</div>${resultMetrics(h)}${resultProgress(h)}<div class="result-card-footer"><span>Explorer mon bilan</span>${icon('arrow','result-open-icon')}</div></summary><div class="day-detail result-card-detail"><div class="result-section-heading"><span>CE QUE TU AS RÉALISÉ</span><small>Meilleure série par charge</small></div>${compactResults(h)}<button class="btn btn-primary btn-wide" data-action="showRecap:${esc(h.id)}">Ouvrir le bilan complet ${icon('up')}</button><button class="link-btn result-replay" data-action="repeatResult:${esc(h.id)}">${icon('plus')}Démarrer une nouvelle séance</button></div></details>`}
function programDayHTML(i,w){const t=templateForDay(i,w),dayName=WEEKDAYS[i];if(t===null)return `<div class="day-card rest-day-card"><div class="day-head"><span class="eyebrow" style="color:var(--blue)">${dayName}</span><span class="pill">Repos</span></div><span class="day-code" aria-hidden="true">0${i+1}</span><h2 class="day-title">RÉCUPÉRATION</h2><p class="day-sub">Aucune séance programmée ce jour, pour cette semaine.</p><div class="spacer"></div><button class="link-btn" data-action="organizeWeek">${icon('edit')}Y mettre une séance</button></div>`;const done=latestDayResult(i,w);if(done)return completedDayHTML(done,i,w);const tpl=program[t],plans=planFor(i,w),custom=hasPlanOverride(w,i);return `<details class="day-card"><summary><div class="day-head"><span class="eyebrow" style="color:${i%3===0?'var(--orange)':i%3===1?'var(--blue)':'var(--pink)'}">${dayName}</span><span class="pill ${custom?'orange':''}">${custom?'Personnalisée · ':''}${plans.length} exercices</span></div><span class="day-code" aria-hidden="true">0${i+1}</span><h2 class="day-title">${esc(tpl.name)}</h2><p class="day-sub">${esc(tpl.focus)}</p><div class="day-bottom"><span class="small muted">${plans.reduce((n,e)=>n+e.sets.length,0)} séries · ${plans.some(e=>e.tag.startsWith('superset'))?'Supersets bras':'Séries classiques'}</span>${icon('chevron','chevron')}</div></summary><div class="day-detail">${plans.map(e=>`<div class="plan-ex"><div class="row between"><b>${esc(e.name)}</b><span class="suggested">${e.load==null?'À régler':fmt(e.load)+' kg'}</span></div><p>${e.sets.length} × ${e.reps} · RIR ${e.rir} · ${esc(e.method)}</p>${e.method.includes('back-off')?`<p>${e.sets.map(s=>s.label+' '+s.reps+' reps'+(s.load==null?'':' à '+fmt(s.load)+' kg')).join(' · ')}</p>`:''}</div>`).join('')}<div class="spacer"></div><div class="stack">${btn('Modifier / réorganiser','editPlan:'+i,'outline','edit')}${btn(w===state.profile.week?'Démarrer la séance':'Utiliser cette semaine','startPreview:'+i,'primary','arrow')}</div></div></details>`}
function completedHomeHTML(h){const s=resultStats(h);return `<section class="card result-home ${s.full?'is-full':''}"><div class="result-top">${resultStatus(h)}<span class="result-date">${resultDate(h)}</span></div><div class="result-title-row"><div><p class="result-caption">${s.full?'TU AS TENU LE CAP.':'CHAQUE SÉRIE COMPTE.'}</p><h2 class="result-home-title">${s.full?'MISSION<br><span>ACCOMPLIE.</span>':'DU TRAVAIL.<br><span>DU PROGRÈS.</span>'}</h2></div>${resultRing(h)}</div><p class="result-home-session">${esc(h.name)}</p>${resultMetrics(h)}${resultProgress(h)}<button class="btn btn-primary btn-wide" data-action="showRecap:${esc(h.id)}">Voir mon bilan ${icon('arrow')}</button></section>`}
function resultExerciseDetails(h){const groups=resultGroups(h),done=groups.filter(e=>e.sets.length),missed=groups.filter(e=>!e.sets.length);return `<section class="recap-section"><div class="result-section-heading"><h3>Ton travail, série par série.</h3><span>${done.length} exercice${done.length>1?'s':''}</span></div><div class="recap-exercises">${done.map((e,i)=>`<details class="recap-exercise" ${done.length===1?'open':''}><summary><span class="recap-ex-index">${String(i+1).padStart(2,'0')}</span><div><b>${esc(e.name)}</b><p>${e.sets.length}${e.total?' / '+e.total:''} séries validées · ${fmt(workload(e.sets),0)} kg de volume</p></div>${icon('chevron')}</summary><div class="recap-table"><div class="recap-table-head"><span>SÉRIE</span><span>CHARGE</span><span>REPS</span><span>RIR</span></div>${e.sets.map((s,index)=>`<div><span><i>${icon('check')}</i>${s.n||index+1}</span><strong>${fmt(s.load)}<small> kg</small></strong><strong>${s.reps}</strong><span>${s.rir??'—'}</span></div>`).join('')}</div></details>`).join('')}</div>${missed.length?`<details class="recap-missed"><summary>${missed.length} exercice${missed.length>1?'s':''} sans série validée ${icon('chevron')}</summary><p>${missed.map(e=>esc(e.name)).join(' · ')}</p></details>`:''}</section>`}
function resultBodyHTML(h,mode='saved'){
 const s=resultStats(h),saved=mode!=='preview',title=s.full?'MISSION<br><span>ACCOMPLIE.</span>':'CHAQUE SÉRIE<br><span>COMPTE.</span>';
 return `<div class="recap-hero"><div class="result-top"><span class="result-status ${s.full?'is-full':''}">${icon(saved?'check':'save')}${saved?'SAUVEGARDÉE DANS TON CARNET':'PRÊTE À ÊTRE ENREGISTRÉE'}</span><span class="result-date">${resultDate(h)}</span></div><div class="recap-hero-layout"><div><h2 class="recap-big-title">${title}</h2><p class="recap-session-name">${esc(h.name)}</p><p class="recap-subline">${h.week!=null?'Semaine '+h.week+' · ':''}${s.exercises} exercice${s.exercises>1?'s':''} réalisé${s.exercises>1?'s':''} · ${s.label.toLowerCase()}</p></div>${resultRing(h)}</div>${resultMetrics(h)}${resultProgress(h)}</div>${saved&&h.records?.length?`<section class="recap-records"><div class="result-section-heading"><h3>${icon('trophy')}${h.records.length} record${h.records.length>1?'s':''} battu${h.records.length>1?'s':''}</h3></div>${h.records.map(r=>`<div><b>${esc(r.name)}</b><strong>${fmt(r.load)} kg <span>× ${r.reps}</span></strong></div>`).join('')}</section>`:''}${resultExerciseDetails(h)}${saved&&h.note?`<section class="recap-note"><span class="eyebrow">TON RESSENTI</span><p>${esc(h.note)}</p></section>`:''}${saved&&h.suggestions?.length?`<details class="recap-next"><summary><span>${icon('arrow')}Pour la prochaine fois</span>${icon('chevron')}</summary><p class="micro muted">Charges de travail proposées lors de l’enregistrement de cette séance. Elles restent ajustables.</p>${h.suggestions.map(x=>`<div class="suggestion"><div><b>${esc(x.name)}</b><p>${esc(x.reason)}</p></div><strong>${fmt(x.load)} kg</strong></div>`).join('')}</details>`:''}<p class="recap-footnote">Volume saisi = charge × répétitions des séries validées. Haltères : charge d’un haltère ; tractions : lest ajouté.</p>`;
}
function presentRecap(h,mode='saved'){
 const preview=mode==='preview';let html=resultBodyHTML(h,mode);
 if(preview)html+=`<section class="recap-note-input"><label for="workoutNote">Comment tu t’es senti ? <span class="muted">Facultatif</span></label><textarea id="workoutNote" rows="2" maxlength="500" placeholder="Bonne énergie, une série difficile, un réglage à garder…"></textarea><p class="micro muted">${resultStats(h).remaining>0?'Seules tes '+h.sets.length+' séries validées seront enregistrées.':'Tes séries sont prêtes à rejoindre ton historique.'}</p></section>`;
 showModal(preview?'Dernier regard avant de valider.':'Ton bilan de séance.',html,preview?[{label:'Revenir à la séance',kind:'outline',fn:closeModal},{label:'Enregistrer la séance',fn:commitWorkout}]:[{label:'Fermer le bilan',fn:closeModal}],true);
 const modal=$('.modal');modal.classList.add('recap-modal');modal.dataset.resultMode=mode;modal.scrollTop=0;
}
function showSessionRecap(id){const h=state.history.find(x=>x.id===id);if(h)presentRecap(h)}
function draftResult(){const d=state.draft;if(!d)return null;const sets=d.exercises.flatMap(e=>e.sets.filter(s=>s.done).map(s=>({name:e.name,n:e.sets.indexOf(s)+1,load:s.load,reps:s.reps,rir:s.rir}))),exercises=d.exercises.map(e=>({name:e.name,done:e.sets.filter(s=>s.done).length,total:e.sets.length}));return {id:d.id,date:new Date().toISOString(),day:d.day,templateDay:d.templateDay,name:program[d.templateDay].name,week:d.week,bodyWeight:d.bodyWeight,duration:Math.max(0,Math.floor((Date.now()-d.started)/1000)),sets,exercises,completion:{done:sets.length,total:exercises.reduce((n,e)=>n+e.total,0)}}}
function finishWorkout(){const h=draftResult();if(!h)return;if(!h.sets.length){toast('Valide au moins une série avant de terminer.');return}presentRecap(h,'preview')}
function commitWorkout(){const d=state.draft;if(!d)return;const h=draftResult();if(!h?.sets.length)return;h.note=$('#workoutNote')?.value||'';h.suggestions=d.exercises.map(nextSuggestion).filter(Boolean);h.records=detectRecords(h.sets,state.history);const old=clone(state);if(state.history.some(x=>x.id===h.id)){toast('Cette séance est déjà enregistrée.');return}state.history.push(h);h.suggestions.forEach(s=>state.workLoads[s.name]=s.load);state.draft=null;if(!save()){state=old;toast('Enregistrement impossible. Ta séance reste ouverte : exporte ton carnet pour la conserver.');return}previewWeek=h.week;releaseWake();closeModal();navigate('home');presentRecap(h,'saved');celebrate()}
function repeatResult(id){const h=state.history.find(x=>x.id===id);if(!h)return;confirmDialog('Commencer une nouvelle séance ?', 'Ton bilan reste enregistré. Une nouvelle séance sera créée à partir du programme actuellement prévu pour ce jour.',()=>startWorkout(h.day,h.week??state.profile.week),'Démarrer une nouvelle séance')}

shell();if(TABINFO.some(t=>t[0]===location.hash.slice(1)))tab=location.hash.slice(1);render();setInterval(tick,500);
